function t02Hop(p) {
  if (p <= 0 || p >= 1) return 0;
  if (p < .3) return -.3 * E.outQuad(p / .3);
  if (p < .55) return -.3 * (1 - E.inQuad((p - .3) / .25));
  if (p < .75) return -.12 * E.outQuad((p - .55) / .2);
  if (p < .9) return -.12 * (1 - E.inQuad((p - .75) / .15));
  return 0;
}
