    alpha(g, 1 - clamp(r / 30), () => { ln(g, px - 7, py, px + 7, py, K.mute, 1); ln(g, px, py - 7, px, py + 7, K.mute, 1); });
    const cp = seg(t, .1, .55) * (1 - seg(t, 1.1, 1.6)), press = seg(t, .5, .58, E.linear) * (1 - seg(t, .62, .72, E.linear));
    cursor(g, lerp(286, px, cp), lerp(176, py, cp), press);
    t04Read(g, `circle(${Math.round(r / Rmax * 150)}% at ${Math.round(px)}px ${Math.round(py)}px)`, 12, 188, r > 0 && r < Rmax * .97 ? K.red : K.mute);
    label(g, 'clip-path: circle()이 넓어진다');
