    circ(g, B.cx, B.cy, 2.5, K.ink);
    // 다이얼
    const dx = 132, dy = 158;
    if (g.createConicGradient) { const ring = g.createConicGradient(a - Math.PI / 2, dx, dy); [[0, K.red], [.33, K.blue], [.66, K.yel], [1, K.red]].forEach(([s, c]) => ring.addColorStop(s, c)); circ(g, dx, dy, 10, null, ring, 4); }
    else circ(g, dx, dy, 10, null, K.mute, 4);
    ln(g, dx, dy, dx + Math.cos(a - Math.PI / 2) * 13, dy + Math.sin(a - Math.PI / 2) * 13, K.ink, 1.5);
    t05R(g, `--angle ${String(Math.round(a / TAU * 360)).padStart(3, ' ')}deg`, dx + 20, dy, K.ink, 'left', 10);
