    const hot = tt => { const [px, py] = cur(tt); return ws.findIndex(w => { const [x, y, bw, bh] = box(w); return px > x && px < x + bw && py > y && py < y + bh; }); };
    T.lines.forEach(l => ln(g, l.x - l.w / 2 - 6, l.y + 4, l.x + l.w / 2 + 6, l.y + 4, K.grid, 1));
    const lifts = ws.map((w, k) => t08Follow(t, tt => [0, hot(tt) === k ? -7 : 0], u => spring(u, 400, 26), .8)[1]);
    T.glyphs.forEach(gl => {
      if (gl.space) return;
      const y = gl.wk != null ? lifts[gl.wk] : 0, k = clamp(-y / 7);
      glyph(g, gl, T, { dy: y, c: t08Mix(K.ink, K.red, k) });
    });
    ws.forEach((w, k) => { const v = clamp(-lifts[k] / 7); if (v > .05) { const ly = T.lines[w.li].y; alpha(g, v, () => { ln(g, w.x - w.w / 2, ly + 4, w.x + w.w / 2, ly + 4, K.red, 1.5); }); } });
    const [cx, cyy] = cur(t); cursor(g, cx, cyy);
    const h = hot(t);
