  values: ['spin 750ms', 'opacity 350ms ease-out', '마스크 0.25em	line-height 0.85–1', 'line-height 0.85–1'], valuesEn: ['spin 750ms', 'opacity 350ms ease-out', 'mask 0.25em', 'line-height 0.85–1'],
  duration: 750, easing: 'ease-out', feel: ['단단함', '경쾌함'], use: ['UI', '영상'],
