// ---- demos-t09.js ----
// ===== t09: 자막(캡션)과 레이아웃 =====

// 자막의 문자 스타일(흰 글자+진한 테두리)
function t09Cap(c, a = 1, lw = 3.5) { return { c: c || K.ink, stroke: K.paper, lw, a }; }
// 영상 프레임(자막 데모 배경. 언덕과 태양뿐인 고요한 그림)
function t09Frame(g, x, y, w, h, seed = 1) {
  rr(g, x, y, w, h, 6, K.card);
  clip(g, x, y, w, h, () => {
    const hy = y + h * .62;
    g.fillStyle = K.grid; g.beginPath(); g.moveTo(x, y + h);
    for (let i = 0; i <= 20; i++) g.lineTo(x + w * i / 20, hy - noise1(i * .55 + seed * 3.1) * h * .2);
    g.lineTo(x + w, y + h); g.closePath(); g.fill();
    circ(g, x + w * .8, y + h * .25, Math.min(10, h * .08), K.grid);
  });
}
// 둥근 모서리 안에만 그림
function t09RClip(g, x, y, w, h, r, fn) { g.save(); rr(g, x, y, w, h, r); g.clip(); fn(); g.restore(); }
// 타임라인(큐의 밴드와 재생 위치)
function t09TL(g, t, dur, cues, y = 182, x0 = 20, x1 = 300) {
  const X = s => lerp(x0, x1, clamp(s / dur));
  ln(g, x0, y, x1, y, K.grid, 1);
  cues.forEach(c => { const on = t >= c[0] && t < c[1]; rr(g, X(c[0]), y - 4, Math.max(2, X(c[1]) - X(c[0])), 8, 2, on ? K.red : K.grid); });
  const px = X(t); ln(g, px, y - 8, px, y + 8, K.ink, 1.2);
  return X;
}
// 문장 구분점(。.!? 기준 최대 2개)
function t09Sent(s) {
  let a = (s.match(/[^。．！？!?.]+[。．！？!?.]*/g) || [s]).map(x => x.trim()).filter(Boolean);
  if (!a.length) a = [s];
  if (a.length > 2) { const h = Math.ceil(a.length / 2), j = isCJK(s) ? '' : ' '; a = [a.slice(0, h).join(j), a.slice(h).join(j)]; }
  return a;
}
// 공백 이외의 단어
function t09Words(s) { return words(s).filter(w => !/^\s+$/.test(w)); }
// 단어를 최대 n개 묶음으로 모음
function t09Group(ws, n, j) {
  if (ws.length <= n) return ws.slice();
  const out = [], per = ws.length / n;
  for (let k = 0; k < n; k++) out.push(ws.slice(Math.round(k * per), Math.round((k + 1) * per)).join(j));
  return out;
}
// 글자 수에 비례한 시간 배분([a,b] 의 배열)
function t09Times(lens, a, b) {
  const tot = lens.reduce((s, x) => s + x, 0) || 1; let c = a;
  return lens.map(x => { const d = (b - a) * x / tot, r = [c, c + d]; c += d; return r; });
}
const t09Mono = (g, s, x, y, c, a = 'left', size = 9) => tx(g, s, x, y, { a, size, w: 500, f: 'm', c: c || K.mute });

// 1. 팝온 자막
R({ id: 'pop-on-subtitle', dur: 4.2, ease: 'linear', still: 1.2,
  f(g, t, o) {
    const cues = t09Sent(TXT(o)), C = cues.length === 2 ? [[.35, 1.95], [2.03, 3.6]] : [[.35, 3.6]];
    label(g, '즉시 표시 / 즉시 삭제');
    t09Frame(g, 20, 24, 280, 136, 1);
    const k = C.findIndex(([a, b]) => t >= a && t < b);
    if (k >= 0) {
      const Ly = layout(g, cues[k], { o, size: 18, maxW: 248, maxLines: 2, y: 134, weight: 700 });
      glyphs(g, Ly, () => t09Cap());
      const n = graphemes(cues[k].replace(/\s/g, '')).length, d = C[k][1] - C[k][0];
      t09Mono(g, `${(n / d).toFixed(1)} cps`, 308, 14, K.ink, 'right');
    } else t09Mono(g, '— cps', 308, 14, K.mute, 'right');
    const X = t09TL(g, t, 4.2, C, 178);
    const fr = Math.floor(t * 24);
    t09Mono(g, `${fr}f`, clamp(X(t), 30, 290), 192, K.ink, 'center', 8);
    if (C.length === 2) { t09Mono(g, 'gap 2f', X(1.99), 167, K.red, 'center', 8); }
    C.forEach(c => { if (Math.abs(fr - Math.round(c[0] * 24)) > 4) t09Mono(g, 'IN', X(c[0]) + 1, 192, K.mute, 'left', 7); });
  },
  descEn: 'A whole subtitle block appears instantly with no animation and vanishes instantly at its out-time.',
  focus: '자막은 한순간 나타나고 한순간 사라진다. 움직임이 없다는 것이 「읽는 시간」을 최대로 한다. 큐와 큐 사이에 최소 2프레임의 공백을 넣으면 같은 위치의 자막이라도 전환이 눈에 보인다.',
  focusEn: 'The block cuts on and off — no motion means the full cue time goes to reading. A gap of at least 2 frames between cues makes a change visible even when the text stays in place.',
  caution: '표시는 최소 5/6초(24fps에서 20프레임), 최장 7초. 영어는 1행 42자·2행까지, 읽는 속도는 어른 20cps·아동 17cps가 기준. 컷 변화점 0.5초 안에 드나들기가 있다면 컷에 맞춤.',
  cautionEn: 'Keep each cue on for at least 5/6 s (20 frames at 24 fps) and no more than 7 s. English: ≤42 chars per line, 2 lines, ≤20 cps for adults / 17 for children. Snap in/out to a shot change within 0.5 s.',
  values: ['최단 20f(5/6초)', '최장 7초	큐 간 ≥ 2f', '큐 간 ≥ 2f', '≤ 42자/행·2행', '≤ 17–20 cps'],
  valuesEn: ['min 20f (5/6 s)', 'max 7 s', 'gap ≥ 2f', '≤ 42 chars/line, 2 lines', '≤ 17–20 cps'],
  duration: 0, easing: 'none (cut)', feel: ['단단함'], use: ['자막', '영상'],
  recipes: {
    css: `/* WebVTT를 그대로 사용. 표시는 컷(애니메이션 없음) */\n/* <video><track kind="subtitles" src="ja.vtt" srclang="ja" default></video> */\nvideo::cue { background: rgb(0 0 0 / .75); color: #fff; font: 700 1em/1.3 sans-serif; }\n\n/* ja.vtt\nWEBVTT\n\n00:00:00.350 --> 00:00:01.950\n가자.\n\n00:00:02.033 --> 00:00:03.600\n이제 시간이 없다. */`,
    remotion: `// 1큐 = 1 Sequence. in/out은 프레임으로 반올림(갭 2f 이상)\nexport const Subs = ({ cues }) => {\n  const { fps } = useVideoConfig();\n  return cues.map((c, i) => (\n    <Sequence key={i} from={Math.round(c.start * fps)} durationInFrames={Math.max(Math.round(fps * 5 / 6), Math.round((c.end - c.start) * fps))} layout="none">\n      <div className="sub">{c.text}</div>\n    </Sequence>\n  ));\n};`
  }
});

// 2. 페인트온 자막
R({ id: 'paint-on-caption', dur: 4.2, ease: 'linear', still: 3.0,
  f(g, t, o) {
    label(g, '덧쓰기(위치 고정)');
    t09Frame(g, 20, 24, 280, 150, 2);
    const Ly = layout(g, TXT(o), { o, size: 20, maxW: 248, maxLines: 2, y: 134, weight: 700 });
    const gl = Ly.glyphs.filter(x => !x.space), n = gl.length;
    const nw = Math.max(1, Ly.realWords.length), r = .12, pause = .14;
    const raw = gl.map((x, i) => i * r + (x.wk || 0) * pause), span = (n - 1) * r + (nw - 1) * pause, sc = span > 2.2 ? 2.2 / span : 1;
    const T = raw.map(v => .35 + v * sc);
    const on = t < 3.75;
    const top = Ly.top, lh = Ly.lineH;
    let last = -1;
    gl.forEach((x, i) => {
      const cy = x.y - Ly.size * .36, shown = on && t >= T[i];
      if (shown) { rr(g, x.x - x.w / 2 - 2, cy - lh / 2, x.w + 4, lh, 0, K.paper); last = i; }
      else if (on) ln(g, x.x - x.w / 2 + 1, cy + Ly.size * .55, x.x + x.w / 2 - 1, cy + Ly.size * .55, K.mute, 1, [2, 2]);
    });
    gl.forEach((x, i) => { if (on && t >= T[i]) glyph(g, x, Ly, { c: K.ink }); });
    // 다음에 쓸 위치의 캐럿
    if (on && last < n - 1) { const nx = gl[last + 1], cy = nx.y - Ly.size * .36, blink = fract(t * 3) < .6 ? 1 : .3; alpha(g, blink, () => rr(g, nx.x - nx.w / 2, cy - lh * .42, 2.5, lh * .84, 1, K.red)); }
    t09Mono(g, `${Math.max(0, last + 1)}/${n}`, 308, 14, K.ink, 'right');
    t09Mono(g, 'reflow 0', 20, 186);
    t09Mono(g, t >= 3.75 ? 'EDM(지우기)' : on && last >= n - 1 ? 'hold' : 'paint', 300, 186, t >= 3.75 ? K.red : K.mute, 'right');
    void top;
  },
  descEn: 'Characters or words are added one by one at fixed positions; once on screen, they never move.',
  focus: '최종 위치는 처음에 정해져 있고(점선), 글자는 그 자리에 덧써질 뿐. 줄바꿈이나 중앙 정렬이 중간에 바뀌지 않으므로 시선을 다시 찾을 필요가 없다.',
  focusEn: 'Final positions are fixed from the start (dotted slots) and glyphs are simply written into them. Wrapping and centring never change mid-way, so the eye never has to re-find the line.',
  caution: '덧쓰면서 중앙 정렬을 다시 하면 줄 전체가 흔들려 읽을 수 없다. 전체 문장을 먼저 조판한 뒤 표시만 전환할 것. 너무 빠른 덧쓰기는 글자가 깜빡이는 것처럼 보인다.',
  cautionEn: 'Re-centring while text is added makes the whole line jitter. Lay out the full text first and only toggle visibility. Very fast painting reads as flicker.',
  values: ['먼저 전문을 조판', '표시만 전환(재배치 0)	글자 1개 ≈ 120ms', '1자 ≈ 120ms', '단어 사이에 쉼'],
  valuesEn: ['lay out full text first', 'toggle visibility only (no reflow)', '≈ 120ms per char', 'short pause between words'],
  duration: 120, easing: 'steps (instant)', feel: ['단단함'], use: ['자막', '영상'],
  recipes: {
    css: `/* 전문을 먼저 나열하고 보이지 않는 상태에서 1글자씩 visibility를 전환한다 */\n.cap span { visibility: hidden; animation: on 0s steps(1) forwards; animation-delay: calc(var(--i) * 120ms); }\n@keyframes on { to { visibility: visible; } }\n@media (prefers-reduced-motion: reduce) { .cap span { animation: none; visibility: visible; } }`,
    waapi: `// 읽기용은 부모에 전문, 분리한 span은 aria-hidden\nconst spans = [...cap.querySelectorAll('span')];\nspans.forEach((s, i) => s.animate([{ visibility: 'hidden' }, { visibility: 'visible' }],\n  { duration: 1, delay: i * 120, fill: 'both' }));`,
    ae: '1. 텍스트 레이어 → 애니메이터: 불투명도 0%\n2. 레인지 셀렉터 → 고급 → 기준: 단어(또는 문자)\n3. 부드러움 0%(순간 전환)\n4. 시작 0% → 100%를 키프레임(위치는 움직이지 않음)',
    aeEn: '1. Text layer → Animate: Opacity 0%\n2. Range Selector → Advanced → Based On: Words (or Characters)\n3. Smoothness 0% (instant switch)\n4. Keyframe Start 0% → 100% (no position change)'
  }
});

// 3. 롤업 자막
R({ id: 'roll-up-caption', dur: 5.0, ease: 'outCubic', still: 3.6,
  f(g, t, o) {
    label(g, '롤업 3행 / 행간 진행 8f');
    t09Frame(g, 20, 24, 280, 152, 3);
    const Ly = layout(g, TXT(o), { o, size: 17, maxW: 200, maxLines: 12, minSize: 12, align: 'left', x: 38, y: 100, weight: 700 });
    const nl = Ly.lines.length, seq = []; for (let k = 0; k < 4; k++) seq.push(k % nl);
    const step = .85, T = seq.map((_, k) => .4 + k * step), rowH = Ly.size * 1.45, bottom = 158;
    const roll = T.reduce((s, tk, k) => s + (k ? seg(t, tk - .27, tk, E.outCubic) : 0), 0);
    const end = 1 - seg(t, 4.55, 4.75, E.linear);
    const wy0 = bottom - rowH * 2.5 - 4, wy1 = bottom + rowH * .5 + 4;
    // 창(3행)과 행번호
    rr(g, 30, wy0, 260, wy1 - wy0, 4, null, K.grid, 1);
    for (let r = 0; r < 3; r++) t09Mono(g, String(13 + r), 284, bottom - (2 - r) * rowH - 3, K.mute, 'right', 7);
    alpha(g, end, () => clip(g, 30, wy0, 260, wy1 - wy0, () => {
      seq.forEach((li, k) => {
        if (t < T[k] - .27) return;
        const line = Ly.lines[li], y = bottom - (roll - k) * rowH, a = clamp(1 - (roll - k - 2), 0, 1);
        const chars = Ly.glyphs.filter(x => x.li === li), nc = Math.max(1, chars.length);
        let x0 = 1e9, x1 = -1e9;
        chars.forEach((x, j) => { if (t >= T[k] + j / nc * .5) { x0 = Math.min(x0, x.x - x.w / 2); x1 = Math.max(x1, x.x + x.w / 2); } });
        alpha(g, a, () => {
          if (x1 > x0) rr(g, x0 - 5, y - Ly.size * .36 - rowH / 2 + 1, x1 - x0 + 10, rowH - 2, 2, K.paper);
          chars.forEach((x, j) => { if (t >= T[k] + j / nc * .5) glyph(g, x, Ly, { c: K.ink, dy: y - x.y }); });
        });
        void line;
      });
    }));
    t09Mono(g, `roll ${roll.toFixed(2)}`, 308, 14, K.ink, 'right');
    if (roll % 1 > .02 && roll % 1 < .98) t09Mono(g, '↑ 1행', 296, wy0 - 6, K.red, 'right');
  },
  descEn: 'Live captions build up one line at a time from the bottom; older lines are pushed upward and roll off.',
  focus: '새 행은 항상 맨 아래에 나타나 오래된 행이 1행분만 위로 밀린다. 읽는 위치(최하행)가 고정되므로 생방송 지연에도 끊기지 않는 글자를 따라가기 쉽다.',
  focusEn: 'New text always lands on the bottom row while older rows shift up by exactly one line. The reading position stays fixed, which makes an unbroken live stream easier to keep up with.',
  caution: '행간을 너무 빠르고 크게 하면 화면 전체가 흘러 어지럽기 쉬움. 3행 정도로 억제하고 화자 얼굴이나 화면 내 문자를 가리지 않는 위치에.',
  cautionEn: 'Large or very fast scroll steps make the whole area swim. Keep to about 3 rows and position the window so it does not cover faces or on-screen text.',
  values: ['2–4행(여기서는 3행)', '행간 6–10f', '새 행은 최하행에', '오래된 행은 위로 밀려남'],
  valuesEn: ['2–4 rows (3 here)', 'roll 6–10 frames', 'new line on the bottom row', 'old lines pushed off the top'],
  duration: 270, easing: 'easeOutCubic', feel: ['경쾌함'], use: ['자막', '영상'],
  recipes: {
    css: `/* 3행분 창. 새 행을 끝에 더하고 전체를 1행분 올린다 */\n.roll { height: calc(3 * 1.45em); overflow: hidden; display: flex; flex-direction: column; justify-content: flex-end; }\n.roll .lines { transition: transform .27s cubic-bezier(.33,1,.68,1); }\n.roll .lines.rolling { transform: translateY(-1.45em); }\n@media (prefers-reduced-motion: reduce) { .roll .lines { transition: none; } }`,
    waapi: `// 행 추가 → 1행분 아래에서 원래 위치로(FLIP). aria-live로 읽기에도 흘린다\nfunction addLine(box, text) {\n  const p = document.createElement('p'); p.textContent = text; box.append(p);\n  while (box.children.length > 3) box.firstElementChild.remove();\n  box.animate([{ transform: 'translateY(1.45em)' }, { transform: 'none' }], { duration: 270, easing: 'cubic-bezier(.33,1,.68,1)' });\n}\n// <div class="roll" aria-live="polite"></div>`
  }
});

// 4. 생자막(2행 블록)
R({ id: 'live-caption-block', dur: 5.4, ease: 'linear', still: 1.6,
  samplesKo: ['태풍 10호는 오늘밤 남해안에 접근할 것으로 보입니다.', '교통 기관의 최신 정보를 확인하십시오.'],
  samplesEn: ['The typhoon will approach tonight.', 'Check transport updates before you leave.'],
  f(g, t, o) {
    const B = TXTS(o).slice(0, 2), C = B.length > 1 ? [[.3, 2.6], [2.6, 4.9]] : [[.3, 4.9]];
    label(g, '2행 블록마다 교체');
    t09Frame(g, 20, 24, 280, 140, 4);
    // 생방송 마크
    circ(g, 34, 36, 3, K.red); t09Mono(g, 'LIVE', 41, 36, K.ink, 'left', 8);
    const by = 106, bh = 50;
    const k = C.findIndex(([a, b]) => t >= a && t < b);
    // 2줄의 상자
    ln(g, 30, by + bh / 2, 290, by + bh / 2, K.grid, 1, [2, 3]);
    if (k >= 0) {
      rr(g, 26, by, 268, bh, 3, K.paper);
      const Ly = layout(g, B[k], { o, size: 17, maxW: 248, maxLines: 2, y: by + bh / 2, weight: 700 });
      glyphs(g, Ly, () => ({ c: K.ink }));
      const n = graphemes(B[k].replace(/\s/g, '')).length, d = C[k][1] - C[k][0];
      t09Mono(g, `${n}${L('글자')} → ${(n / 270 * 60).toFixed(1)}s`, 308, 14, K.ink, 'right');
    }
    // 교체 순간
    const X = t09TL(g, t, 5.4, C, 182);
    if (C.length > 1) {
      const sw = 1 - seg(t, 2.6, 3.1, E.linear);
      if (t >= 2.6 && sw > 0) alpha(g, sw, () => { rr(g, 26, by, 268, bh, 3, null, K.red, 1.5); });
      t09Mono(g, '교체', X(2.6), 171, t >= 2.6 && t < 3.1 ? K.red : K.mute, 'center', 8);
    }
    t09Mono(g, '≤ 2행 · 30자 · 270자/분', 290, 36, K.mute, 'right', 8);
  },
  descEn: 'A two-line block is replaced wholesale by the next block — no scrolling.',
  focus: '줄이 흐르지 않으므로 블록이 떠 있는 동안 위치가 완전히 멈춰 있음. 교체 순간만이 「다음으로 넘어갔다」는 신호가 됨.',
  focusEn: 'Nothing scrolls, so the text is perfectly still while a block is up. The hard swap itself is the only cue that the caption has moved on.',
  caution: '1블록 2행·30자 이내. 실측하면 분당 약 270자(영화 자막 기준 240자/분 초과)가 되기 쉬우므로 요약(원 발화의 56–71% 정도)로 양을 억제한다.',
  cautionEn: 'Max 2 lines / 30 characters per block. Measured live output runs ~270 chars/min — faster than the 240 chars/min film guideline — so summarise (about 56–71% of the spoken text).',
  values: ['2행 / 30자', '교체(스크롤 없음)', '약 270자/분(실측)', '영화 기준 240자/분', '요약률 0.56–0.71'],
  valuesEn: ['2 lines / 30 chars', 'swap (no scrolling)', '≈ 270 chars/min measured', 'film guideline 240 chars/min', 'summary ratio 0.56–0.71'],
  duration: 0, easing: 'none (cut)', feel: ['단단함'], use: ['자막', '영상'],
  recipes: {
    css: `/* 2행 고정 띠. 내용을 통째로 교체할 뿐(transition 없음) */\n.live { position: absolute; inset: auto 4% 6%; min-height: 2.6em; max-width: 30em;\n  background: #000c; color: #fff; font: 700 clamp(16px, 3.4vw, 28px)/1.3 sans-serif;\n  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }`,
    waapi: `// 블록 단위로 교체. 읽기는 aria-live에 맡긴다\nconst box = document.querySelector('.live');\nbox.setAttribute('aria-live', 'polite');\nfunction show(block) { box.textContent = block; /* 애니메이션하지 않음 */ }\nsocket.onmessage = e => show(JSON.parse(e.data).block);`
  }
});

// 5. 현재 단어 하이라이트 자막
R({ id: 'word-highlight-caption', dur: 4.6, ease: 'outCubic', still: 2.0,
  f(g, t, o) {
    label(g, 'fromMs ≤ t < toMs의 단어를 강조');
    const Ly = layout(g, TXT(o), { o, size: 30, maxW: 272, maxLines: 2, y: 82, weight: 800 });
    const ws = Ly.realWords, T = t09Times(ws.map(w => w.i1 - w.i0 + 1), .4, 3.4);
    const page = seg(t, .15, .3, E.outCubic) * (1 - seg(t, 4.15, 4.35, E.linear));
    let act = -1;
    glyphs(g, Ly, gl => {
      const k = gl.wk, w = ws[k]; if (w == null) return null;
      const [a, b] = T[k], p = seg(t, a, a + .08, E.outCubic) * (1 - seg(t, b, b + .08, E.outCubic));
      if (t >= a && t < b) act = k;
      const s = 1 + .1 * p;
      return Object.assign(t09Cap(p > .5 ? K.red : K.ink, page, 4), { sx: s, dx: (gl.x - w.x) * (s - 1), dy: -2 * p });
    });
    // 토큰의 타임라인(음성 파형 포함)
    const x0 = 24, x1 = 296, y = 168, X = s => lerp(x0, x1, s / 4.6);
    for (let x = x0; x <= x1; x += 3) {
      const s = (x - x0) / (x1 - x0) * 4.6, sp = T.some(([a, b]) => s >= a && s < b - .03);
      const h = sp ? 3 + noise1(x * .21, 4) * 13 : 1.5;
      ln(g, x, y - 14 - h / 2, x, y - 14 + h / 2, s <= t ? K.blue : K.grid, 1.5);
    }
    T.forEach(([a, b], k) => { const on = k === act; rr(g, X(a) + .5, y - 3, X(b) - X(a) - 1, 7, 2, on ? K.red : K.grid); });
    ln(g, X(t), y - 26, X(t), y + 6, K.ink, 1.2);
    if (act >= 0) t09Mono(g, `${Math.round(T[act][0] * 1000)}–${Math.round(T[act][1] * 1000)}ms`, 308, 14, K.ink, 'right');
    t09Mono(g, 'scale 1 → 1.1', 24, 190); t09Mono(g, `t = ${Math.round(t * 1000)}ms`, 296, 190, K.mute, 'right');
  },
  descEn: 'Captions appear a few words per page; only the word being spoken is highlighted by colour and scale, synced to the audio.',
  focus: '자막 페이지 자체는 멈춘 채 강조만 음성 타이밍에 맞춰 단어에서 단어로 옮겨간다. 확대는 1.1배까지이므로 주변 단어 위치는 거의 흔들리지 않는다.',
  focusEn: 'The page stays still; only the emphasis hops word to word on the audio timing. Capping the scale at 1.1× keeps neighbouring words from shifting.',
  caution: '강조색에만 의미를 싣지 않는다(색각 차이). 확대로 이웃 단어와 겹치지 않게 자간에 여유를. 1페이지는 3–5단어 정도로 정리한다.',
  cautionEn: 'Do not rely on colour alone (colour-vision differences). Leave enough spacing that the 1.1× scale never collides with neighbours. Keep pages to about 3–5 words.',
  values: ['combineTokens 800–1500ms', '강조 scale 1.0 → 1.1', '1페이지 3–5단어', 'white-space: pre'],
  valuesEn: ['combineTokens 800–1500ms', 'active scale 1.0 → 1.1', '3–5 words per page', 'white-space: pre'],
  duration: 80, easing: 'easeOutCubic', feel: ['경쾌함'], use: ['자막', '영상', '광고'],
  recipes: {
    remotion: `import { createTikTokStyleCaptions } from '@remotion/captions';\nconst { pages } = createTikTokStyleCaptions({ captions, combineTokensWithinMilliseconds: 1200 });\n\nconst Page = ({ page }) => {\n  const frame = useCurrentFrame(); const { fps } = useVideoConfig();\n  const t = page.startMs + (frame / fps) * 1000;\n  return <div style={{ whiteSpace: 'pre' }}>{page.tokens.map(tk => {\n    const on = tk.fromMs <= t && t < tk.toMs;\n    return <span key={tk.fromMs} style={{ display: 'inline-block', color: on ? '#7d64ff' : '#fff', transform: \`scale(\${on ? 1.1 : 1})\` }}>{tk.text}</span>;\n  })}</div>;\n};\n// pages.map(p => <Sequence from={p.startMs / 1000 * fps}><Page page={p} /></Sequence>)`,
    css: `/* JS에서 현재 단어에 .on을 붙인다. 읽기용 전문은 별도로 둔다 */\n.page span { display: inline-block; transition: transform 80ms cubic-bezier(.33,1,.68,1), color 80ms; }\n.page span.on { color: var(--accent); transform: scale(1.1); }\n@media (prefers-reduced-motion: reduce) { .page span.on { transform: none; text-decoration: underline; } }`,
    ae: '1. 단어마다 마커(음성에 맞춤)\n2. 애니메이터: 채우기 컬러+스케일 110%\n3. 레인지 셀렉터 → 단위: 인덱스, 기준: 단어\n4. 시작/종료를 마커에 맞춰 1단어씩 진행(홀드 키)',
    aeEn: '1. Add a marker per word (synced to the audio)\n2. Animator: Fill Color + Scale 110%\n3. Range Selector → Units: Index, Based On: Words\n4. Step Start/End one word at a time on the markers (hold keys)'
  }
});

// 6. 배경 필 이동
R({ id: 'highlight-pill', dur: 4.4, ease: 'outCubic', still: 2.2,
  f(g, t, o) {
    label(g, '필이 단어에서 단어로 100ms');
    const Ly = layout(g, TXT(o), { o, size: 34, maxW: 260, maxLines: 2, y: 92, weight: 800 });
    const ws = Ly.realWords, n = ws.length, T = ws.map((_, k) => .4 + k * 3 / n);
    const pad = Ly.size * .22, h = Ly.size * 1.18;
    const rect = w => { const ly = Ly.lines[w.li].y - Ly.size * .36; return [w.x - w.w / 2 - pad, ly - h / 2, w.w + pad * 2, h]; };
    // 단어의 사각형(측정한 위치)
    ws.forEach(w => { const [x, y, ww, hh] = rect(w); g.setLineDash([2, 3]); rr(g, x, y, ww, hh, hh / 2, null, K.grid, 1); g.setLineDash([]); });
    let k = 0; T.forEach((a, i) => { if (t >= a) k = i; });
    const p = seg(t, T[k], T[k] + .1, E.outCubic), A = rect(ws[Math.max(0, k - 1)]), Bb = rect(ws[k]);
    let [px, py, pw, ph] = k === 0 ? Bb : A.map((v, i) => lerp(v, Bb[i], p));
    const grow = seg(t, .3, .42, E.outCubic) * (1 - seg(t, 3.85, 4.0, E.inCubic));
    const cx = px + pw / 2; pw *= grow; px = cx - pw / 2;
    const draw = (c) => glyphs(g, Ly, () => ({ c }));
    draw(K.ink);
    if (grow > .01) { rr(g, px, py, pw, ph, ph / 2, K.red); t09RClip(g, px, py, pw, ph, ph / 2, () => draw(K.paper)); }
    t09Mono(g, `left ${Math.round(px)}  width ${Math.round(pw)}`, 308, 14, K.ink, 'right');
    // 진행 인디케이터
    ws.forEach((_, i) => circ(g, 160 + (i - (n - 1) / 2) * 12, 172, 2.5, i === k && grow > .5 ? K.red : K.grid));
    t09Mono(g, '100ms ease-out', 160, 188, K.mute, 'center');
  },
  descEn: 'A rounded coloured box slides behind the spoken word, gliding from word to word.',
  focus: '필은 사라지지 않고 다음 단어로 「미끄러지므로」 눈은 박스만 따라가면 된다. 박스 안의 글자는 반전색이 되고 폭도 단어 길이에 맞춰 늘었다 줄어든다.',
  focusEn: 'The pill never disappears — it glides to the next word, so the eye just follows the box. Text inside inverts, and the box width stretches to each word.',
  caution: '이동을 너무 길게 하면 음성보다 늦게 보임(80–120ms가 기준). 반전 색 글자와 배경의 대비를 확인한다.',
  cautionEn: 'Long moves visibly lag the audio — stay around 80–120ms. Check contrast of the inverted text against the pill.',
  values: ['이동 80–120ms', 'ease-out', 'left / width 보간', '필 내부는 반전색'],
  valuesEn: ['move 80–120ms', 'ease-out', 'interpolate left / width', 'inverted text inside'],
  duration: 100, easing: 'easeOutCubic', feel: ['경쾌함'], use: ['자막', '영상', 'UI'],
  recipes: {
    gsap: `// 각 단어의 사각형을 재서 필의 x / width로 옮긴다\nconst pill = document.querySelector('.pill');\nfunction go(word) {\n  const r = word.getBoundingClientRect(), p = word.parentElement.getBoundingClientRect();\n  gsap.to(pill, { x: r.left - p.left - 8, width: r.width + 16, duration: .1, ease: 'power2.out' });\n  words.forEach(w => w.classList.toggle('on', w === word)); // .on { color: #0d1320 }\n}`,
    css: `.line { position: relative; }\n.pill { position: absolute; inset-block: -.1em; left: 0; width: 0; border-radius: 999px; background: var(--accent); z-index: -1;\n  transition: translate .1s cubic-bezier(.33,1,.68,1), width .1s cubic-bezier(.33,1,.68,1); }\n.word.on { color: #0d1320; transition: color .1s; }\n@media (prefers-reduced-motion: reduce) { .pill { transition: none; } }`,
    remotion: `// 현재 단어의 사각형(미리 measureText로 계산)으로 보간\nconst k = tokens.findIndex(tk => tk.fromMs <= ms && ms < tk.toMs);\nconst p = interpolate(ms - tokens[k].fromMs, [0, 100], [0, 1], { extrapolateRight: 'clamp', easing: Easing.out(Easing.cubic) });\nconst prev = rects[Math.max(0, k - 1)], cur = rects[k];\nconst left = interpolate(p, [0, 1], [prev.x, cur.x]), width = interpolate(p, [0, 1], [prev.w, cur.w]);`
  }
});

// 7. 숏폼 영상 팝 자막
R({ id: 'hormozi-caption', dur: 3.8, ease: 'outBack', still: 1.25,
  f(g, t, o) {
    label(g, '1페이지 1단어 / 150ms 팝');
    const txt = TXT(o), cjk = isCJK(txt);
    const pages = t09Group(t09Words(txt), 4, cjk ? '' : ' ').map(s => s.toUpperCase());
    const n = pages.length; let key = 0; pages.forEach((p, i) => { if (graphemes(p).length >= graphemes(pages[key]).length) key = i; });
    // 화자 실루엣
    circ(g, 160, 58, 24, K.card); g.fillStyle = K.card; g.beginPath(); g.ellipse(160, 168, 70, 62, 0, Math.PI, TAU); g.fill();
    const S = pages.map((_, i) => .25 + i * .62);
    let k = -1; S.forEach((s, i) => { if (t >= s) k = i; });
    const out = seg(t, 3.3, 3.45, E.inCubic);
    if (k >= 0 && out < 1) {
      const dt = t - S[k], isKey = k === key;
      const sc = kf(dt, [[0, .8], [.1, 1.1], [.18, 1]], E.outQuad) * (1 - out * .3);
      const Ly = layout(g, pages[k], { o, size: isKey ? 52 : 42, maxW: 250, maxLines: 2, y: 118, weight: 900 });
      const rot = isKey ? -4 * Math.PI / 180 * seg(dt, 0, .12, E.outBack) : 0;
      alpha(g, seg(dt, 0, .05, E.linear) * (1 - out), () => xf(g, 160, 118, sc, sc, rot, () => {
        g.translate(-160, -118);
        glyphs(g, Ly, () => ({ c: K.paper, stroke: K.paper, lw: 9, dy: 3, dx: 2 }));
        glyphs(g, Ly, () => ({ c: isKey ? K.red : K.ink, stroke: K.paper, lw: 7 }));
      }));
      t09Mono(g, `${k + 1}/${n}${isKey ? '  key ±4°' : ''}`, 308, 14, isKey ? K.red : K.ink, 'right');
      t09Mono(g, `scale ${sc.toFixed(2)}`, 308, 188, K.mute, 'right');
    }
    // 페이지 열
    pages.forEach((_, i) => rr(g, 14 + i * 14, 184, 10, 4, 2, i === k && out < 1 ? (i === key ? K.red : K.ink) : K.grid));
  },
  descEn: 'Heavy uppercase captions pop in one to three words at a time; the key word is larger, brightly coloured and tilted.',
  focus: '페이지에 단어가 하나뿐이라 시선은 화면 중앙에서 움직이지 않는다. 0.8 → 1.1 → 1.0의 짧은 탄력과 키워드만의 색·기울기로 리듬이 생긴다.',
  focusEn: 'One word per page keeps the eye parked at centre. A short 0.8 → 1.1 → 1.0 bounce plus colour and tilt on the key word create the rhythm.',
  caution: '모든 단어를 강조하면 아무것도 강조되지 않는다. 키워드는 1페이지에 1개까지. 굵은 테두리가 없으면 밝은 영상 위에서 읽히지 않는다.',
  cautionEn: 'Emphasising every word emphasises nothing — at most one key word per page. Without a heavy outline the text disappears over bright footage.',
  values: ['weight 900·대문자	scale 0.8 → 1.1 → 1.0', 'scale 0.8 → 1.1 → 1.0', '150ms', '키워드 ±3–5°', 'combineTokens ≈ 300–600ms'],
  valuesEn: ['weight 900, uppercase', 'scale 0.8 → 1.1 → 1.0', '150ms', 'key word ±3–5°', 'combineTokens ≈ 300–600ms'],
  duration: 150, easing: 'easeOutBack', feel: ['바운스', '경쾌함'], use: ['자막', '광고', '영상'],
  recipes: {
    remotion: `const { pages } = createTikTokStyleCaptions({ captions, combineTokensWithinMilliseconds: 400 });\nconst Page = ({ text, isKey }) => {\n  const frame = useCurrentFrame(); const { fps } = useVideoConfig();\n  const s = interpolate(frame, [0, .1 * fps, .15 * fps], [.8, 1.1, 1], { extrapolateRight: 'clamp' });\n  return <div style={{ font: '900 72px Montserrat', textTransform: 'uppercase', WebkitTextStroke: '10px #000', paintOrder: 'stroke',\n    color: isKey ? '#f2c84b' : '#fff', transform: \`scale(\${s}) rotate(\${isKey ? -4 : 0}deg)\` }}>{text}</div>;\n};`,
    css: `.cap { font: 900 clamp(32px, 9vw, 72px)/1 Montserrat, sans-serif; text-transform: uppercase;\n  -webkit-text-stroke: .14em #000; paint-order: stroke fill; animation: pop .15s ease-out both; }\n.cap.key { color: #f2c84b; rotate: -4deg; }\n@keyframes pop { 0% { scale: .8; } 66% { scale: 1.1; } 100% { scale: 1; } }\n@media (prefers-reduced-motion: reduce) { .cap { animation: none; } }`,
    ae: '1. 단어마다 별도 레이어(또는 소스 텍스트를 마커로 전환)\n2. 스케일 80% → 110% → 100%(0 / 3 / 5프레임)\n3. 키워드만 채우기를 노란색, 회전 -4°, 조금 크게\n4. 레이어 스타일: 테두리 10px + 드롭 섀도',
    aeEn: '1. One layer per word (or switch Source Text on markers)\n2. Scale 80% → 110% → 100% (frames 0 / 3 / 5)\n3. Key word only: yellow fill, rotate -4°, a little larger\n4. Layer Style: Stroke 10px + Drop Shadow'
  }
});

// 8. 자막 스프링 팝
R({ id: 'caption-spring-pop', dur: 3.8, spring: [100, 10, 1], still: 2.4,
  f(g, t, o) {
    label(g, 'spring 100 / 10 / 1 · 5f 차');
    const Ly = layout(g, TXT(o), { o, size: 34, maxW: 272, maxLines: 2, y: 74, weight: 800 });
    const ws = Ly.realWords, st = 5 / 30, t0 = .3;
    const fade = 1 - seg(t, 3.25, 3.5, E.linear);
    glyphs(g, Ly, gl => {
      const k = gl.wk; if (k == null) return null; const w = ws[k];
      const p = spring(t - t0 - k * st, 100, 10, 1), s = .6 + .4 * p;
      return { c: k === ws.length - 1 ? K.red : K.ink, a: clamp(p) * fade, sx: s, dx: (gl.x - w.x) * (s - 1), ay: .6 };
    });
    // 스프링의 곡선과 각 단어의 현재 위치
    const gx = 44, gw = 236, gy = 176, gh = 46, Tm = 1.4, X = u => gx + gw * u / Tm, Y = v => gy - gh * v / 1.2;
    ln(g, gx, gy, gx + gw, gy, K.grid, 1); ln(g, gx, Y(1), gx + gw, Y(1), K.grid, 1, [3, 3]);
    t09Mono(g, '1.0', gx - 4, Y(1), K.mute, 'right', 8); t09Mono(g, '0', gx - 4, gy, K.mute, 'right', 8);
    g.beginPath(); for (let i = 0; i <= 80; i++) { const u = Tm * i / 80; g.lineTo(X(u), Y(spring(u, 100, 10, 1))); } g.strokeStyle = K.mute; g.lineWidth = 1.2; g.stroke();
    ws.forEach((w, k) => { const u = t - t0 - k * st; if (u > 0 && u < Tm && fade > 0) { const c = k === ws.length - 1 ? K.red : K.ink; circ(g, X(u), Y(spring(u, 100, 10, 1)), 3.2, c); } });
    const sp = springStats(100, 10, 1);
    t09Mono(g, `overshoot ${Math.round(sp.over)}%`, 308, 14, K.ink, 'right');
    t09Mono(g, 'scale 0.6 → 1', gx + gw, gy + 10, K.mute, 'right', 8);
  },
  descEn: 'Caption words spring out one by one with a bouncy scale, wobbling like a spring before they settle.',
  focus: 'ζ ≈ 0.5 스프링이라 약 16% 넘어선 뒤 돌아온다. 5프레임 차로 단어마다 위상이 어긋나 흔들림이 파도처럼 오른쪽으로 전파된다. 아래 그래프의 점이 각 단어의 현재 위치.',
  focusEn: 'With ζ ≈ 0.5 the spring overshoots by about 16% and settles back. A 5-frame offset puts each word at a different phase, so the wobble ripples to the right — the dots on the curve are each word right now.',
  caution: '흔들림이 길면 읽기 시작이 늦어진다. 자막에서는 damping을 올린다(15–20) 또는 overshoot를 몇 %로 억제한다. 모션 감소 설정에서는 페이드만.',
  cautionEn: 'A long wobble delays reading. For captions raise damping (15–20) or keep overshoot to a few percent. With reduced motion, fall back to a plain fade.',
  values: ['5프레임 차', 'damping 10 / stiffness 100 / mass 1', 'scale 0.6 → 1', 'opacity = spring 값'],
  valuesEn: ['stagger 5 frames', 'damping 10 / stiffness 100 / mass 1', 'scale 0.6 → 1', 'opacity = spring value'],
  duration: 800, easing: 'spring(100, 10, 1)', feel: ['바운스'], use: ['자막', '영상', '광고'],
  recipes: {
    remotion: `const frame = useCurrentFrame(); const { fps } = useVideoConfig();\nreturn words.map((w, i) => {\n  const s = spring({ frame: frame - i * 5, fps, config: { damping: 10, stiffness: 100, mass: 1 } });\n  return <span key={i} style={{ display: 'inline-block', opacity: Math.min(1, s),\n    transform: \`scale(\${interpolate(s, [0, 1], [0.6, 1])})\` }}>{w}&nbsp;</span>;\n});`,
    motion: `import { animate, stagger } from 'motion';\nanimate('.cap .w', { scale: [0.6, 1], opacity: [0, 1] },\n  { type: 'spring', stiffness: 100, damping: 10, mass: 1, delay: stagger(5 / 30) });`,
    css: `/* linear()로 스프링 근사(ζ≈0.5） */\n.w { display: inline-block; animation: pop .8s linear(0, .45 12%, .98 25%, 1.16 35%, 1.08 50%, .98 65%, 1.01 80%, 1) both;\n  animation-delay: calc(var(--i) * 167ms); }\n@keyframes pop { from { scale: .6; opacity: 0; } to { scale: 1; opacity: 1; } }\n@media (prefers-reduced-motion: reduce) { .w { animation: none; } }`
  }
});

// 9. 가라오케 칠하기
R({ id: 'karaoke-fill', dur: 4.8, ease: 'linear', still: 2.2,
  f(g, t, o) {
    label(g, '단어 길이만큼 왼쪽에서 칠함');
    const Ly = layout(g, TXT(o), { o, size: 30, maxW: 272, maxLines: 2, y: 80, weight: 800 });
    const ws = Ly.realWords, T = t09Times(ws.map(w => w.i1 - w.i0 + 1), .4, 3.6);
    const fade = 1 - seg(t, 4.2, 4.5, E.linear);
    glyphs(g, Ly, () => t09Cap(K.ink, 1, 4));
    let act = -1;
    ws.forEach((w, k) => {
      const [a, b] = T[k], p = clamp((t - a) / (b - a)); if (t >= a && t < b) act = k;
      if (p <= 0 || fade <= 0) return;
      const ly = Ly.lines[w.li].y, x0 = w.x - w.w / 2 - 1, fw = (w.w + 2) * p;
      alpha(g, fade, () => clip(g, x0, ly - Ly.size * 1.1, fw, Ly.size * 1.5, () => glyphs(g, Ly, gl => gl.wk === k ? t09Cap(K.red, 1, 4) : null)));
      if (p < 1) ln(g, x0 + fw, ly - Ly.size * .9, x0 + fw, ly + Ly.size * .2, K.ink, 1);
    });
    // \kf의 룰러
    const x0 = 24, x1 = 296, y = 160, X = s => lerp(x0, x1, (s - .2) / 3.6);
    ws.forEach((w, k) => {
      const [a, b] = T[k], on = k === act, wd = X(b) - X(a) - 1.5;
      rr(g, X(a), y - 6, wd, 12, 2, on ? K.red : t >= b && fade > .5 ? K.blue : K.grid);
      if (wd > 34) t09Mono(g, `\\kf${Math.round((b - a) * 100)}`, X(a) + wd / 2, y, on ? K.paper : K.ink, 'center', 8);
    });
    ln(g, clamp(X(t), x0, x1), y - 11, clamp(X(t), x0, x1), y + 11, K.ink, 1.2);
    if (act >= 0) t09Mono(g, `{\\kf${Math.round((T[act][1] - T[act][0]) * 100)}}  ${Math.round(clamp((t - T[act][0]) / (T[act][1] - T[act][0])) * 100)}%`, 308, 14, K.ink, 'right');
    t09Mono(g, '1cs = 10ms', 296, 182, K.mute, 'right', 8);
  },
  descEn: 'Each lyric word (syllable) is wiped with colour from left to right over exactly the time it is sung.',
  focus: '채움 속도는 단어마다 다르다. 길게 끄는 단어는 천천히, 짧은 단어는 한순간 채워지므로 글자가 「노래의 길이」를 그대로 보여준다.',
  focusEn: 'Wipe speed differs per word: held notes fill slowly, short ones snap. The text literally shows how long each word is sung.',
  caution: '채움색과 원래 색의 명도 차를 크게 한다(경계가 보이지 않으면 의미가 없다). 채움은 선형 그대로(이징을 주면 노래와 어긋나 보인다).',
  cautionEn: 'Make the filled and base colours differ strongly in lightness, or the wipe edge is lost. Keep the wipe linear — easing makes it drift from the singing.',
  values: ['채움 0% → 100%(단어 길이)	선형·clamp', '선형·clamp', '\\kf 단위 1/100초', '단어별로 다른 속도'],
  valuesEn: ['fill 0% → 100% over token duration', 'linear, clamped', '\\kf in centiseconds', 'different speed per word'],
  duration: 0, easing: 'linear', feel: ['부드러움'], use: ['자막', '영상'],
  recipes: {
    remotion: `// 토큰별 채움률. 범위 밖은 clamp\nconst ms = (frame / fps) * 1000;\nreturn tokens.map(tk => {\n  const p = interpolate(ms, [tk.fromMs, tk.toMs], [0, 100], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });\n  return <span key={tk.fromMs} style={{ background: \`linear-gradient(90deg, #ff725e \${p}%, #fff \${p}%)\`,\n    WebkitBackgroundClip: 'text', backgroundClip: 'text', color: 'transparent' }}>{tk.text}</span>;\n});`,
    css: `/* 단어마다 --d(부르는 길이)를 넣는다 */\n.syl { background: linear-gradient(90deg, var(--accent) 50%, #fff 50%) 100% 0 / 200% 100%;\n  -webkit-background-clip: text; background-clip: text; color: transparent;\n  animation: fill var(--d) linear var(--at) forwards; }\n@keyframes fill { to { background-position: 0 0; } }`,
    canvas: `// 칠한 색의 복사본을 clip으로 잘라내어 겹친다\nctx.fillStyle = '#fff'; ctx.fillText(word, x, y);\nconst p = Math.min(1, Math.max(0, (t - from) / (to - from)));\nctx.save(); ctx.beginPath(); ctx.rect(x, y - size, width * p, size * 1.4); ctx.clip();\nctx.fillStyle = accent; ctx.fillText(word, x, y); ctx.restore();`,
    ae: '1. 애니메이터: 채우기 컬러(악센트 색)\n2. 레인지 셀렉터 → 단위: 인덱스, 기준: 문자\n3. 단어마다 시작/끝을 박자에 맞춰 키(리니어)\n4. ASS 자막이라면 {\\kf45} 처럼 1/100초로 지정',
    aeEn: '1. Animator: Fill Color (accent)\n2. Range Selector → Units: Index, Based On: Characters\n3. Key Start/End per word on the beat (linear)\n4. In ASS subtitles use {\\kf45} (centiseconds)'
  }
});

// 10. 강제 자막 페이드 동기
R({ id: 'forced-narrative-fade', dur: 4.6, ease: 'linear', still: 2.0,
  f(g, t, o) {
    label(g, '페이드 중간에서 in / out');
    const src = u => kf(u, [[0, 0], [.4, 0], [1.0, 1], [2.8, 1], [3.4, 0], [4.6, 0]], E.linear);
    const sub = u => kf(u, [[0, 0], [.55, 0], [.85, 1], [2.95, 1], [3.25, 0], [4.6, 0]], E.linear);
    t09Frame(g, 20, 24, 280, 104, 5);
    // 화면 안의 간판(원본 그래픽)
    alpha(g, src(t), () => {
      rr(g, 110, 38, 100, 46, 5, K.ink);
      circ(g, 130, 61, 12, K.red); rr(g, 122, 59, 16, 4, 1, K.ink);
      [[148, 52, 50], [148, 61, 40], [148, 70, 46]].forEach(([x, y, w]) => rr(g, x, y, w, 4, 2, K.mute));
      ln(g, 160, 84, 160, 96, K.ink, 3);
    });
    const Ly = layout(g, TXT(o), { o, size: 17, maxW: 250, maxLines: 1, y: 113, weight: 700 });
    glyphs(g, Ly, () => t09Cap(K.ink, sub(t)));
    // 두 줄의 불투명도 커브
    const gx = 50, gw = 246, gy0 = 140, gy1 = 176, X = u => gx + gw * u / 4.6, Y = v => lerp(gy1, gy0, v);
    const curve = (fn, c, fill) => { g.beginPath(); for (let i = 0; i <= 92; i++) { const u = 4.6 * i / 92; g.lineTo(X(u), Y(fn(u))); }
      if (fill) { g.lineTo(X(4.6), gy1); g.lineTo(X(0), gy1); g.closePath(); g.fillStyle = K.grid; g.fill(); } else { g.strokeStyle = c; g.lineWidth = 1.6; g.stroke(); } };
    curve(src, null, true); curve(sub, K.red);
    [.7, 3.1].forEach(m => { ln(g, X(m), gy0 - 4, X(m), gy1, K.mute, 1, [2, 2]); t09Mono(g, '½', X(m), gy0 - 8, K.mute, 'center', 8); });
    t09Mono(g, '영상', gx - 6, gy1 - 6, K.mute, 'right', 8); t09Mono(g, '자막', gx - 6, gy0 + 4, K.red, 'right', 8);
    ln(g, X(t), gy0 - 2, X(t), gy1 + 2, K.ink, 1.2);
    t09Mono(g, `${L('영상')} ${Math.round(src(t) * 100)}%  ${L('자막')} ${Math.round(sub(t) * 100)}%`, 308, 14, K.ink, 'right');
    t09Mono(g, '\\fad(300,300)', gx + gw, 190, K.mute, 'right', 8);
  },
  descEn: 'A translated subtitle for on-screen text (a sign) fades in and out in sync with the original graphic.',
  focus: '자막은 간판과 동시가 아니라 간판 페이드의 「중간점」에서 드나든다. 반쯤 보였을 때 번역이 나오므로 원문과 번역이 함께 나타나 함께 사라지는 것처럼 느껴진다.',
  focusEn: 'The subtitle does not start with the sign but at the midpoint of the sign’s fade. The translation arrives when the sign is half visible, so the two feel like they appear and leave together.',
  caution: '화면 내 문자가 나온 채로 컷이 끝난다면 자막은 컷 2프레임 전에 지움. 대화 자막과 겹칠 때는 위치를 나눔(위에 놓는 등).',
  cautionEn: 'If the on-screen text holds until a cut, end the subtitle 2 frames before the cut. When it overlaps dialogue subtitles, separate the positions (e.g. place it at the top).',
  values: ['in/out = 원래 페이드의 중간', '컷 2f 전에 종료', '\\fad(in,out) 밀리초', '[간판] 따위의 괄호 표기'],
  valuesEn: ['in/out at the midpoint of the source fade', 'end 2f before a shot change', '\\fad(in,out) in ms', 'bracketed label like [SIGN]'],
  duration: 300, easing: 'linear', feel: ['부드러움'], use: ['자막', '영상'],
  recipes: {
    css: `/* 간판 페이드(0.4–1.0s)의 중간 0.7s에 자막 중심을 맞춘다 */\n.forced { animation: fn 2.7s linear .55s both; }\n@keyframes fn { 0% { opacity: 0; } 11% { opacity: 1; } 89% { opacity: 1; } 100% { opacity: 0; } }\n@media (prefers-reduced-motion: reduce) { .forced { animation-timing-function: steps(1, jump-none); } }`,
    waapi: `// 원 그래픽의 페이드 구간에서 자막의 in/out을 구한다\nconst mid = (a, b) => (a + b) / 2;\nconst tin = mid(srcIn0, srcIn1), tout = mid(srcOut0, srcOut1), f = 300;\nsub.animate([{ opacity: 0 }, { opacity: 1, offset: f / (tout - tin) }, { opacity: 1, offset: 1 - f / (tout - tin) }, { opacity: 0 }],\n  { delay: tin * 1000 - f / 2, duration: (tout - tin) * 1000 + f, fill: 'both' });`
  }
});

// 11. RSVP 한 단어 제시
R({ id: 'rsvp-flash', dur: 4.2, ease: 'linear', still: 3.6,
  f(g, t, o) {
    label(g, 'ORP(35%)를 중앙에 고정');
    const ws = t09Words(TXT(o)).slice(0, 10), base = .2;
    const iv = ws.map(w => base * (/[.,!?。、！？]$/.test(w) || graphemes(w).length > 8 ? 1.5 : 1));
    const pass = iv.reduce((a, b) => a + b, 0), passes = Math.max(1, Math.floor(2.4 / pass));
    const seq = []; for (let p = 0; p < passes; p++) ws.forEach((w, i) => seq.push(i));
    const fam = FAM(o), wt = 700;
    const orp = w => { const c = graphemes(w); return Math.min(c.length - 1, Math.floor(c.length * .35)); };
    // 글자 크기(모든 단어가 중앙 표시에서 벗어나지 않는 크기)
    let size = 40; ws.forEach(w => { const c = graphemes(w), i = orp(w); setFont(g, 40, wt, fam);
      const lw = g.measureText(c.slice(0, i).join('')).width + g.measureText(c[i]).width / 2, rw = g.measureText(c.slice(i + 1).join('')).width + g.measureText(c[i]).width / 2;
      size = Math.min(size, 40 * 140 / Math.max(lw, rw, 1)); });
    const cx = 160, cy = 96;
    // 프레임과 표식
    ln(g, 24, cy - 32, 296, cy - 32, K.grid, 1); ln(g, 24, cy + 28, 296, cy + 28, K.grid, 1);
    ln(g, cx, cy - 32, cx, cy - 24, K.red, 1.5); ln(g, cx, cy + 20, cx, cy + 28, K.red, 1.5);
    let c = 0, k = -1; const t0 = .35;
    for (let j = 0; j < seq.length; j++) { if (t >= t0 + c) k = j; c += iv[seq[j]]; }
    const show = k >= 0 && t < 3.85;
    if (show) {
      const w = ws[seq[k]], ch = graphemes(w), i = orp(w);
      setFont(g, size, wt, fam); g.textBaseline = 'middle';
      const ow = g.measureText(ch[i]).width;
      g.fillStyle = K.ink; g.textAlign = 'right'; g.fillText(ch.slice(0, i).join(''), cx - ow / 2, cy);
      g.textAlign = 'left'; g.fillText(ch.slice(i + 1).join(''), cx + ow / 2, cy);
      g.fillStyle = K.red; g.textAlign = 'center'; g.fillText(ch[i], cx, cy);
      t09Mono(g, `${(k % ws.length) + 1}/${ws.length}`, 308, 14, K.ink, 'right');
    }
    // 단어 나열(현재 단어에 밑줄)
    const line = ws.join(isCJK(ws.join('')) ? ' ' : ' ');
    const ss = fitSize(g, line, 270, 10, 500, FONT.m);
    setFont(g, ss, 500, FONT.m); const full = g.measureText(line).width; let x = 160 - full / 2;
    ws.forEach((w, i) => { const ww = g.measureText(w).width, on = show && seq[k] === i; tx(g, w, x, 152, { a: 'left', size: ss, w: 500, f: 'm', c: on ? K.ink : K.mute }); if (on) ln(g, x, 159, x + ww, 159, K.red, 1.5); x += ww + g.measureText(' ').width; setFont(g, ss, 500, FONT.m); });
    t09Mono(g, '300 wpm = 200ms / 단어', 160, 182, K.mute, 'center');
  },
  descEn: 'Words flash one at a time in the same spot at high speed, with each word’s recognition letter always aligned to a centre mark.',
  focus: '단어 길이가 달라져도 빨간 글자(ORP: 단어의 약 35% 위치)만은 중앙 표식에서 움직이지 않음. 눈을 옮기지 않아도 되어 빠르게 읽히지만 그만큼 되돌아갈 수 없음.',
  focusEn: 'Word length changes, but the red letter (ORP, ~35% into the word) never leaves the centre mark. No eye movement means fast reading — but also no going back.',
  caution: '같은 위치 제시로 약 585 wpm으로 빨라지는 한편 이해도가 떨어진다는 보고가 있다. 문장부호나 긴 단어에서는 표시를 1.5–2배로 늘리고 일시정지와 되감기를 반드시 준비한다.',
  cautionEn: 'Same-position RSVP reaches ~585 wpm vs 316 with eye movements, but comprehension costs are reported. Extend punctuation/long words by 1.5–2× and always provide pause and rewind.',
  values: ['300 wpm → 200ms / 단어', '문장부호·긴 단어 +50–100%', 'ORP ≈ 단어의 35%', '585 vs 316 wpm(연구)'],
  valuesEn: ['300 wpm → 200ms per word', '+50–100% on punctuation / long words', 'ORP ≈ 35% into the word', '585 vs 316 wpm (study)'],
  duration: 200, easing: 'steps (instant)', feel: ['단단함', '경쾌함'], use: ['UI', '본문'],
  recipes: {
    canvas: `// ORP 글자의 중심을 항상 cx에 둔다\nconst orp = w => Math.min(w.length - 1, Math.floor(w.length * .35));\nfunction drawWord(ctx, w, cx, cy) {\n  const i = orp(w), ow = ctx.measureText(w[i]).width;\n  ctx.textAlign = 'right'; ctx.fillStyle = '#fff'; ctx.fillText(w.slice(0, i), cx - ow / 2, cy);\n  ctx.textAlign = 'left'; ctx.fillText(w.slice(i + 1), cx + ow / 2, cy);\n  ctx.textAlign = 'center'; ctx.fillStyle = accent; ctx.fillText(w[i], cx, cy);\n}\nconst delay = w => 60000 / wpm * (/[.,!?]$/.test(w) || w.length > 8 ? 1.5 : 1);`,
    css: `/* 3개의 span(앞·ORP·뒤)을 grid로 중앙 열에 맞춘다 */\n.rsvp { display: grid; grid-template-columns: 1fr auto 1fr; font: 700 2rem/1 sans-serif; }\n.rsvp .pre { text-align: right; } .rsvp .orp { color: var(--accent); } .rsvp .post { text-align: left; }\n/* 읽기용으로 전문을 별도 준비하고 .rsvp는 aria-hidden="true" */`,
    remotion: `const { fps } = useVideoConfig(); const frame = useCurrentFrame();\nconst per = Math.round(fps * 60 / 300); // 300 wpm\nconst w = words[Math.min(words.length - 1, Math.floor(frame / per))];\nconst i = Math.min(w.length - 1, Math.floor(w.length * .35));\nreturn <div className="rsvp"><span className="pre">{w.slice(0, i)}</span><span className="orp">{w[i]}</span><span className="post">{w.slice(i + 1)}</span></div>;`
  }
});

// 12. 어절 줄바꿈 자막
R({ id: 'phrase-line-break', dur: 4.6, ease: 'outExpo', still: 2.2,
  f(g, t, o) {
    label(g, '고정 글자 수 / 어절로 줄바꿈');
    const txt = TXT(o), ch = graphemes(txt), n = ch.length, cjk = isCJK(txt);
    // 고정 글자 수: 일본어는 6글자마다(긴 문장은 3줄에 들어가는 글자 수), 언문은 글자 수의 절반으로 기계적으로 자름
    const N = cjk ? (n <= 18 ? 6 : Math.ceil(n / 3)) : Math.ceil(n / 2);
    const chunk = k => { const out = []; for (let i = 0; i < n; i += k) out.push(ch.slice(i, i + k).join('').trim()); return out.filter(Boolean); };
    // 어절(단어) 경계에서 가운데에 가장 가까운 위치
    let acc = 0, best = -1; const ws = words(txt);
    ws.forEach((w, i) => { if (i && !/^\s+$/.test(w) && (best < 0 || Math.abs(acc - n / 2) < Math.abs(best - n / 2))) best = acc; acc += graphemes(w).length; });
    const split = b => b > 0 && b < n ? [ch.slice(0, b).join('').trim(), ch.slice(b).join('').trim()] : [txt];
    const A = n > N ? chunk(N) : [txt], B = split(best);
    const fam = FAM(o), wt = 700;
    const size = Math.min(20, 54 / (Math.max(A.length, B.length) * 1.25), ...[...A, ...B].map(s => fitSize(g, s, 214, 20, wt, fam)));
    const s1 = Math.min(size, fitSize(g, txt, 220, size, wt, fam));
    const p0 = .45;
    const merge = seg(t, 3.85, 4.4, E.inOut);
    const plate = (lines, y, tag, f, good) => {
      rr(g, 72, y, 236, 66, 6, K.card);
      t09Mono(g, tag, 14, y + 12, good ? K.red : K.mute, 'left', 9);
      t09Mono(g, `F ${f}%`, 14, y + 28, good ? K.ink : K.mute, 'left', 9);
      const k = lines.length;
      const one = layout(g, txt, { o, size: s1, maxW: 9999, maxLines: 1, minSize: s1, x: 190, y: y + 33, weight: wt });
      const two = lines.map((s, i) => layout(g, s, { o, size, maxW: 9999, maxLines: 1, minSize: size, x: 190, y: y + 33 + (i - (k - 1) / 2) * size * 1.25, weight: wt }));
      const tg = two.flatMap(Ly => Ly.glyphs.filter(x => !x.space).map(x => ({ x, Ly })));
      const og = one.glyphs.filter(x => !x.space);
      clip(g, 72, y, 236, 66, () => tg.forEach(({ x, Ly }, j) => {
        const sg = og[j] || x, p = k > 1 ? stag(t, j, tg.length, p0, .5 / Math.max(1, tg.length), .55, E.outExpo) * (1 - merge) : 1;
        const cs = lerp(s1, size, p), cyv = lerp(sg.y - s1 * .36, x.y - size * .36, p);
        glyph(g, x, Ly, { c: K.ink, size: cs, dx: (sg.x - x.x) * (1 - p), dy: cyv - (x.y - cs * .36) });
      }));
      if (k > 1) { const a = seg(t, 1.0, 1.2, E.linear) * (1 - merge); two.slice(0, -1).forEach(Ly => { const l1 = Ly.lines[0]; alpha(g, a, () => t09Mono(g, '↵', l1.x + l1.w / 2 + 4, l1.y - size * .36, good ? K.red : K.mute, 'left', 11)); }); }
    };
    plate(A, 30, `${N}${L('글자별')}`, 21, false);
    plate(B, 108, L('분절'), 74, true);
  },
  descEn: 'Subtitle line breaks fall on phrase or clause boundaries instead of a fixed character count, splitting the text into two readable chunks.',
  focus: '같은 문장도 줄바꿈 위치만으로 읽기 쉬움이 크게 달라진다. 위는 글자 수로 기계적으로 끊어 단어 중간에서 갈라지고, 아래는 어절 경계로 끊으므로 1행씩이 의미의 덩어리가 된다.',
  focusEn: 'Same sentence, very different readability. The top breaks at a fixed count and can split mid-word; the bottom breaks at a phrase boundary so each line is a unit of meaning.',
  caution: '어절을 우선해도 2행 길이가 지나치게 다르면 읽기 어렵다. 조사를 행 머리에 두지 않고, 수식어와 피수식어를 떨어뜨리지 않는다. 글자 수 제한(1행 상한)은 별도로 지킨다.',
  cautionEn: 'Even with phrase breaks, wildly uneven lines read badly. Never start a line with a particle or split a modifier from its head, and still respect the per-line character limit.',
  values: ['어절·절 경계로 줄바꿈	F 값 74% vs 21%(고정 6자)', 'F값 74% vs 21%(고정 6자)', 'word-break: auto-phrase', 'BudouX'],
  valuesEn: ['break at phrase / clause boundaries', 'F 74% vs 21% (fixed 6 chars)', 'word-break: auto-phrase', 'BudouX'],
  duration: 550, easing: 'easeOutExpo', feel: ['부드러움'], use: ['자막', '제목', '본문'],
  recipes: {
    css: `/* Chromium 119+: 일본어를 분절 단위로 줄바꿈 */\n.sub { word-break: auto-phrase; text-wrap: balance; max-inline-size: 15em; }\n/* 미대응 환경에서는 BudouX가 <wbr> 를 넣는다 */`,
    remotion: `import { loadDefaultJapaneseParser } from 'budoux';\nconst parser = loadDefaultJapaneseParser();\n// 분절로 나누고 가운데에 가장 가까운 경계로 2행으로 나눈다\nconst chunks = parser.parse(text);\nlet acc = 0, best = 0;\nchunks.forEach((c, i) => { if (i && Math.abs(acc - text.length / 2) < Math.abs(best - text.length / 2)) best = acc; acc += c.length; });\nreturn <div className="sub">{text.slice(0, best)}<br />{text.slice(best)}</div>;`
  }
});

// 13. 폭에 딱 맞는 제목
R({ id: 'fit-text-title', dur: 4.2, ease: 'inOut', still: 0.2,
  f(g, t, o) {
    label(g, 'fitText: 폭에서 글자 크기 역산');
    const fw = kf(t, [[0, 280], [.4, 280], [1.2, 150], [2.2, 150], [3.0, 280], [4.2, 280]], E.inOut);
    const x0 = 160 - fw / 2, y0 = 34, h = 118, pad = 14, within = fw - pad * 2;
    rr(g, x0, y0, fw, h, 6, K.card, K.grid, 1);
    g.setLineDash([3, 3]); rr(g, x0 + pad, y0 + 8, within, h - 16, 2, null, K.mute, 1); g.setLineDash([]);
    const txt = TXT(o), cap = 92;
    const fit = fitSize(g, txt, within, 400, WGT(o), FAM(o)), size = Math.min(cap, fit);
    const Ly = layout(g, txt, { o, size, maxW: 9999, maxLines: 1, minSize: size, y: y0 + h / 2 });
    plain(g, Ly, K.ink);
    // 폭의 치수선
    const ay = y0 + h + 14;
    ln(g, x0 + pad, ay, x0 + pad + within, ay, K.red, 1);
    ln(g, x0 + pad, ay - 4, x0 + pad, ay + 4, K.red, 1); ln(g, x0 + pad + within, ay - 4, x0 + pad + within, ay + 4, K.red, 1);
    t09Mono(g, `withinWidth ${Math.round(within)}`, 160, ay + 12, K.red, 'center');
    t09Mono(g, `fontSize ${Math.round(size)}px${fit > cap ? ' (max)' : ''}`, 308, 14, K.ink, 'right');
    // 드래그 중 상자
    const press = seg(t, .35, .45, E.linear) * (1 - seg(t, 1.2, 1.3, E.linear)) + seg(t, 2.15, 2.25, E.linear) * (1 - seg(t, 3.0, 3.1, E.linear));
    cursor(g, x0 + fw - 2, y0 + h - 14, press);
  },
  descEn: 'A title auto-sizes to fill the frame width exactly, staying edge to edge as the frame or text length changes.',
  focus: '상자 폭이 바뀔 때마다 글자 크기가 역산되어 항상 좌우 여백에 딱 맞는다. 글자 수가 아니라 「폭」이 제목 크기를 정한다.',
  focusEn: 'Every width change re-derives the font size, so the title always meets the padding exactly. Width, not character count, sets the size.',
  caution: '1–2글자면 거대해지므로 상한(max)을 정한다. 폰트가 로드되기 전에 재면 폭이 어긋나므로 로드 완료를 기다린 뒤 계산한다.',
  cautionEn: 'One or two characters would blow up — set a maximum. Measuring before the font loads gives the wrong width, so wait for the font first.',
  values: ['withinWidth = 틀 폭 − 여백', 'fontSize = 폭 ÷ 잰 폭', '상한 크기에서 정체', '폰트 로드 후 측정'],
  valuesEn: ['withinWidth = frame width − padding', 'fontSize = width ÷ measured width', 'cap at a max size', 'measure after the font loads'],
  duration: 800, easing: 'easeInOut', feel: ['단단함'], use: ['제목', '영상', '로고'],
  recipes: {
    remotion: `import { fitText } from '@remotion/layout-utils';\nconst { fontSize } = fitText({ text, withinWidth: width - 2 * 80, fontFamily: 'Pretendard', fontWeight: '800', validateFontIsLoaded: true });\nreturn <h1 style={{ fontSize: Math.min(fontSize, 240), fontFamily: 'Pretendard', fontWeight: 800, whiteSpace: 'nowrap' }}>{text}</h1>;`,
    css: `/* 컨테이너 쿼리 단위로 근사(글자 수 n을 커스텀 프로퍼티로 전달) */\n.frame { container-type: inline-size; padding-inline: 14px; }\n.title { font-size: min(calc(100cqi / (var(--n) * .62)), 96px); white-space: nowrap; }`,
    canvas: `// 한 번 재서 비례로 정한다(폭은 글자 크기에 비례)\nawait document.fonts.load('800 100px Pretendard');\nctx.font = '800 100px Pretendard';\nconst size = Math.min(96, 100 * within / ctx.measureText(text).width);`
  }
});

// 14. 등폭 스택
R({ id: 'stacked-justified', dur: 4.4, ease: 'outCubic', still: 3.0,
  f(g, t, o) {
    label(g, '각 단어를 같은 폭으로 확대·축소');
    const txt = TXT(o), cjk = isCJK(txt);
    const ws = t09Group(t09Words(txt), 5, cjk ? '' : ' ');
    const fam = FAM(o), wt = WGT(o), gap = 6;
    const m = ws.map(w => { setFont(g, 40, wt, fam); const r = g.measureText(w); return { w, l: r.actualBoundingBoxLeft, bw: r.actualBoundingBoxLeft + r.actualBoundingBoxRight, a: r.actualBoundingBoxAscent, d: r.actualBoundingBoxDescent }; });
    let TW = 168;
    const calc = () => m.map(x => Math.min(110, 40 * TW / Math.max(1, x.bw)));
    let S = calc(), tot = () => S.reduce((s, v, i) => s + (m[i].a + m[i].d) * v / 40, 0) + gap * (ws.length - 1);
    if (tot() > 136) { TW *= 136 / tot(); S = calc(); }
    const n = ws.length, P = ws.map((_, k) => seg(t, .3 + k * .45, .3 + k * .45 + .3, E.outCubic));
    const out = seg(t, 3.75, 4.1, E.inCubic);
    const hgt = k => (m[k].a + m[k].d) * S[k] / 40;
    const Hc = P.reduce((s, p, k) => s + p * (hgt(k) + (k ? gap : 0)), 0);
    let y = 104 - Hc / 2 - out * 10, bx = 160 - TW / 2;
    // 가이드(블록 좌우)
    ln(g, bx, 26, bx, 174, K.grid, 1, [3, 3]); ln(g, bx + TW, 26, bx + TW, 174, K.grid, 1, [3, 3]);
    t09Mono(g, `w = ${Math.round(TW)}px`, 160, 186, K.mute, 'center');
    alpha(g, 1 - out, () => ws.forEach((w, k) => {
      const p = P[k]; if (p <= 0) return;
      const s = S[k], hh = hgt(k);
      if (k) y += gap * p;
      const base = y + m[k].a * s / 40 + (1 - p) * 26;
      alpha(g, p, () => {
        setFont(g, s, wt, fam); g.textAlign = 'left'; g.textBaseline = 'alphabetic';
        g.fillStyle = k === n - 1 ? K.red : K.ink; g.fillText(w, bx + m[k].l * s / 40, base);
        t09Mono(g, `${Math.round(s)}px`, bx + TW + 8, y + hh / 2, K.mute, 'left', 8);
      });
      y += hh * p;
    }));
  },
  descEn: 'Words of different lengths are each scaled to the same width and stack one by one into a solid rectangular block.',
  focus: '짧은 단어일수록 크고 긴 단어일수록 작아져 좌우 끝(점선)이 딱 맞는다. 새 단어가 아래에서 들어올 때마다 쌓인 블록 전체가 위로 밀린다.',
  focusEn: 'Short words grow, long words shrink, and every edge lands on the dotted guides. Each new word slides in from below and pushes the whole stack up.',
  caution: '글자 크기 차이가 너무 크면 작은 단어를 읽을 수 없다. 너무 짧은 단어(1글자 등)는 상한 크기에서 멈춘다. 강조할 단어를 짧게 하면 자연스럽게 커진다.',
  cautionEn: 'Huge size differences make the small words unreadable. Cap very short words (single characters). Making the key word short naturally makes it biggest.',
  values: ['scale = 목표 폭 ÷ 단어 폭	1단어마다 8–10f로 쌓음', '단어마다 8–10f로 쌓는다', 'actualBoundingBox로 실측 크기를 잰다', '상한 크기 있음'],
  valuesEn: ['scale = target width ÷ word width', 'stack one word per 8–10 frames', 'measure ink bounds (actualBoundingBox)', 'capped max size'],
  duration: 300, easing: 'easeOutCubic', feel: ['경쾌함', '무거움'], use: ['제목', '영상', '광고'],
  recipes: {
    gsap: `// 단어마다 폭을 맞춘 뒤 1행씩 쌓는다\nconst W = block.clientWidth;\nlines.forEach(el => gsap.set(el, { fontSize: parseFloat(getComputedStyle(el).fontSize) * W / el.scrollWidth }));\ngsap.from(lines, { yPercent: 100, autoAlpha: 0, duration: .3, ease: 'power3.out', stagger: .45 });`,
    css: `/* 1단어 1행. --k(목표 폭 / 자연스러운 폭)은 JS로 넣는다 */\n.stack { inline-size: 12ch; line-height: .9; }\n.stack span { display: block; inline-size: max-content; font-size: calc(1em * var(--k)); animation: in .3s cubic-bezier(.33,1,.68,1) both; animation-delay: calc(var(--i) * .45s); }\n@keyframes in { from { translate: 0 100%; opacity: 0; } }\n@media (prefers-reduced-motion: reduce) { .stack span { animation: none; } }`,
    ae: '1. 단어 1개 레이어 1개\n2. 스케일에 표현식:\n   w = sourceRectAtTime().width; s = 600 / w * 100; [s, s]\n3. 위치를 직전 레이어 아래 끝에 맞춘다\n4. 8–10프레임씩 어긋나게 아래에서 슬라이드 인',
    aeEn: '1. One layer per word\n2. Scale expression:\n   w = sourceRectAtTime().width; s = 600 / w * 100; [s, s]\n3. Position each layer under the previous one\n4. Offset by 8–10 frames and slide in from below'
  }
});

// 15. 레이아웃 추종 단어 교체
R({ id: 'layout-word-insert', dur: 5.0, spring: [300, 30, 1], still: 1.4,
  f(g, t, o) {
    label(g, 'layout: 주변이 새 폭으로');
    const txt = TXT(o); let pre = '', slot = txt, post = '';
    const m = txt.match(/^(.*?)\[(.+?)\](.*)$/);
    if (m) { pre = m[1]; slot = m[2]; post = m[3]; }
    else { const ws = words(txt), real = ws.filter(w => !/^\s+$/.test(w)); if (real.length >= 2) { const li = ws.lastIndexOf(real[real.length - 1]); slot = ws[li]; pre = ws.slice(0, li).join(''); post = ws.slice(li + 1).join(''); } }
    const alt = isCJK(slot + pre + post) ? ['전달하다', '디자인하기', '만들기'] : ['ship', 'design', 'make'];
    const seq = [slot, ...alt.filter(a => a !== slot)].slice(0, 3);
    const fam = FAM(o), wt = WGT(o), pad = 7;
    let size = 30; const meas = s => textW(g, s, size, wt, fam);
    const widest = Math.max(...seq.map(s => meas(pre) + meas(s) + meas(post) + pad * 2));
    if (widest > 268) size *= 268 / widest;
    const pw = meas(pre), qw = meas(post), sw = seq.map(meas);
    const C = [.4, 2.0, 3.6], idx = t < C[0] ? 0 : t < C[1] ? 1 : t < C[2] ? 2 : 0;
    const keys = [[0, sw[0]], [C[0], sw[1]], [C[1], sw[2]], [C[2], sw[0]]];
    const cw = track(t, keys, 300, 30, 1) + pad * 2, total = pw + cw + qw, x0 = 160 - total / 2, cy = 92;
    // 외곽 프레임(컨테이너도 layout)
    rr(g, x0 - 14, cy - size * .95, total + 28, size * 1.9, 8, K.card, K.grid, 1);
    const font = () => { setFont(g, size, wt, fam); g.textBaseline = 'middle'; g.fillStyle = K.ink; };
    font(); g.textAlign = 'left'; g.fillText(pre, x0, cy); g.fillText(post, x0 + pw + cw, cy);
    // 슬롯
    const sx = x0 + pw, sh = size * 1.3;
    rr(g, sx, cy - sh / 2, cw, sh, 6, null, K.red, 1.5);
    clip(g, sx, cy - sh / 2, cw, sh, () => {
      const last = [-1, ...C].filter(c => c <= t).pop(), prev = idx === 0 ? 2 : idx - 1, dt = t - last;
      const pin = last < 0 ? 1 : seg(dt, 0, .35, E.outExpo), pout = last < 0 ? 1 : seg(dt, 0, .25, E.inCubic);
      font(); g.textAlign = 'center'; g.fillStyle = K.red;
      alpha(g, pin, () => g.fillText(seq[idx], sx + cw / 2, cy + (1 - pin) * sh * .7));
      if (pout < 1) alpha(g, 1 - pout, () => g.fillText(seq[prev], sx + cw / 2, cy - pout * sh * .7));
    });
    t09Mono(g, `width ${Math.round(cw - pad * 2)}px`, 160, cy + size + 18, K.red, 'center');
    seq.forEach((s, i) => rr(g, 160 + (i - 1) * 14 - 4, 176, 8, 4, 2, i === idx ? K.red : K.grid));
    t09Mono(g, 'spring 300 / 30', 308, 14, K.ink, 'right');
  },
  descEn: 'When a word in a sentence is swapped for one of a different length, the surrounding words and container slide smoothly to their new positions.',
  focus: '바뀌는 것은 1단어뿐이어도 앞뒤 단어와 외곽 프레임이 함께 스프링으로 움직이므로 문 전체가 하나의 덩어리로 늘었다 줄어든다. 단어는 프레임 안에서 상하로 교체된다.',
  focusEn: 'Only one word changes, but the words around it and the container spring to their new positions, so the whole sentence stretches and shrinks as one. The word itself swaps vertically inside its slot.',
  caution: '교체 간격이 짧으면 다 읽기 전에 바뀐다(2–3초는 표시). 주변 단어가 크게 움직이면 읽기 어려우므로 교체할 단어는 문장 끝이나 독립된 행에 두는 것이 좋다.',
  cautionEn: 'Swapping too often changes the word before it is read — keep each for 2–3 s. Big shifts of surrounding words hurt reading, so put the swap slot at the end or on its own line.',
  values: ['spring stiffness 300 / damping 30', '교체 간격 2–3초', 'layout 애니메이션', '단어는 위아래로 드나듦'],
  valuesEn: ['spring stiffness 300 / damping 30', 'word interval 2–3 s', 'layout animation', 'word exits up / enters from below'],
  duration: 400, easing: 'spring(300, 30)', feel: ['부드러움', '말랑함'], use: ['제목', 'UI'],
  recipes: {
    motion: `import { motion, AnimatePresence } from 'motion/react';\nconst t = { type: 'spring', stiffness: 300, damping: 30 };\n<motion.p layout transition={t} className="box">\n  <motion.span layout transition={t}>우리는</motion.span>\n  <motion.span layout transition={t} className="slot" style={{ display: 'inline-block', overflow: 'hidden' }}>\n    <AnimatePresence mode="popLayout" initial={false}>\n      <motion.span key={word} initial={{ y: '100%', opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={{ y: '-100%', opacity: 0 }}>{word}</motion.span>\n    </AnimatePresence>\n  </motion.span>\n  <motion.span layout transition={t}>회사입니다</motion.span>\n</motion.p>`,
    css: `/* interpolate-size로 width:auto 보간(Chromium 129+) */\n:root { interpolate-size: allow-keywords; }\n.slot { display: inline-block; width: auto; overflow: clip; transition: width .4s cubic-bezier(.2,.9,.3,1.05); }\n@media (prefers-reduced-motion: reduce) { .slot { transition: none; } }\n/* 읽기: aria-live="polite" 를 붙인 요소에 현재 단어만 넣는다 */`
  }
});

// 16. 아나그램 재정렬
R({ id: 'anagram-flip', dur: 4.2, bez: [.2, .8, .2, 1], still: 1.6,
  f(g, t, o) {
    label(g, 'FLIP: 같은 글자가 이동');
    const txt = TXT(o); let [a, b] = txt.split(/\s*(?:→|->|⇒)\s*/);
    if (!b) { const c = graphemes(a); const r = rng(c.length * 31 + 7); let d = c.slice();
      for (let k = 0; k < 6; k++) { d = c.slice(); for (let i = d.length - 1; i > 0; i--) { const j = Math.floor(r() * (i + 1)); [d[i], d[j]] = [d[j], d[i]]; } if (d.join('') !== a) break; }
      b = d.length > 1 && d.join('') === a ? d.slice().reverse().join('') : d.join(''); }
    let A = layout(g, a, { o, size: 46, maxW: 280, maxLines: 1, y: 92 }), B = layout(g, b, { o, size: 46, maxW: 280, maxLines: 1, y: 92 });
    const s = Math.min(A.size, B.size);
    A = layout(g, a, { o, size: s, maxW: 9999, maxLines: 1, y: 92 }); B = layout(g, b, { o, size: s, maxW: 9999, maxLines: 1, y: 92 });
    const used = new Set(), pairs = [], ga = A.glyphs.filter(x => !x.space), gb = B.glyphs.filter(x => !x.space);
    const newB = [];
    gb.forEach(y => { const x = ga.find(q => !used.has(q.i) && q.ch === y.ch); if (x) { used.add(x.i); pairs.push([x, y]); } else newB.push(y); });
    const goneA = ga.filter(x => !used.has(x.i));
    pairs.sort((p, q) => p[0].i - q[0].i);
    const ez = bez(.2, .8, .2, 1), n = pairs.length;
    // 갈 때(0.4s~)와 올 때(2.3s~)
    const prog = j => stag(t, j, n, .4, .02, .6, ez) - stag(t, j, n, 2.3, .02, .6, ez);
    const whole = seg(t, .4, 1.0, ez) - seg(t, 2.3, 2.9, ez);
    // 슬롯
    (whole > .5 ? gb : ga).forEach(x => ln(g, x.x - x.w / 2 + 2, 92 + s * .3, x.x + x.w / 2 - 2, 92 + s * .3, K.grid, 1.5));
    pairs.forEach(([x, y], j) => {
      const p = prog(j), dx = y.x - x.x, dir = dx >= 0 ? -1 : 1, arc = Math.min(40, 16 + Math.abs(dx) * .18);
      const st = { dx: dx * p, dy: dir * arc * Math.sin(Math.PI * clamp(p)) };
      glyph(g, x, A, Object.assign({ c: K.ink }, st));
      const hot = Math.sin(Math.PI * clamp(p)); if (hot > .02) glyph(g, x, A, Object.assign({ c: K.red, a: hot }, st));
    });
    goneA.forEach(x => glyph(g, x, A, { c: K.ink, a: 1 - whole, dy: -10 * whole }));
    newB.forEach(y => glyph(g, y, B, { c: K.ink, a: whole, dy: 10 * (1 - whole) }));
    // 두 단어
    const lab = `${a}  →  ${b}`, ls = fitSize(g, lab, 280, 11, 500, FONT.m);
    setFont(g, ls, 500, FONT.m); const aw = g.measureText(a + '  →  ').width, lw = g.measureText(lab).width;
    tx(g, a + '  →  ', 160 - lw / 2, 158, { a: 'left', size: ls, w: 500, f: 'm', c: whole < .5 ? K.ink : K.mute });
    tx(g, b, 160 - lw / 2 + aw, 158, { a: 'left', size: ls, w: 500, f: 'm', c: whole >= .5 ? K.red : K.mute });
    t09Mono(g, '0.6s · stagger 0.02s', 160, 182, K.mute, 'center');
  },
  descEn: 'The letters of one word physically travel to new places and rearrange into a different word made of the same letters.',
  focus: '사라졌다 다른 단어가 나오는 것이 아니라 같은 글자가 각자 새 위치로 호를 그리며 옮아감. 오른쪽으로 가는 글자는 위로, 왼쪽으로 가는 글자는 아래로 지나 부딪히지 않는다.',
  focusEn: 'Nothing fades — each letter arcs to its new slot. Letters moving right pass above, letters moving left pass below, so they never collide.',
  caution: '이동 중에는 단어로 읽을 수 없음. 이동은 0.6초 정도로 억제하고 앞뒤 단어를 확실히 정지시킨다. 스크린리더에는 최종 단어만 전달.',
  cautionEn: 'Mid-move the word is unreadable — keep the move around 0.6 s and hold both words still. Give screen readers only the final word.',
  values: ['0.6초', 'cubic-bezier(.2,.8,.2,1)', 'stagger 0.02s', '같은 글자를 대응시킴'],
  valuesEn: ['duration 0.6s', 'ease cubic-bezier(.2,.8,.2,1)', 'stagger 0.02s', 'map identical letters'],
  duration: 600, easing: 'cubic-bezier(.2,.8,.2,1)', feel: ['부드러움'], use: ['제목', '로고'],
  recipes: {
    waapi: `// FLIP: 위치 기록 → 재정렬 → 차분을 transform으로 되돌려 0으로\nconst first = new Map([...el.children].map(c => [c, c.getBoundingClientRect()]));\norder.forEach(c => el.append(c)); // 새 단어 순서대로 DOM 재정렬\n[...el.children].forEach((c, i) => {\n  const f = first.get(c), l = c.getBoundingClientRect();\n  c.animate([{ transform: \`translate(\${f.left - l.left}px, \${f.top - l.top}px)\` }, { transform: 'none' }],\n    { duration: 600, delay: i * 20, easing: 'cubic-bezier(.2,.8,.2,1)' });\n});\nel.setAttribute('aria-label', newWord); // 글자 span은 aria-hidden`,
    gsap: `const state = Flip.getState('.word .ch');\nreorder(); // 같은 글자 요소를 새 순서로 다시 배열\nFlip.from(state, { duration: .6, ease: 'power3.out', stagger: .02 });`,
    motion: `// 글자마다 안정된 key(글자+출현 번호)를 붙이면 layout으로 이동한다\n<p>{letters.map(l => <motion.span key={l.id} layout transition={{ duration: .6, ease: [.2, .8, .2, 1] }}>{l.ch}</motion.span>)}</p>`
  }
});

// 17. 균형 줄바꿈과 재분할
R({ id: 'balanced-reflow', dur: 4.8, ease: 'outExpo', still: 3.4,
  f(g, t, o) {
    label(g, 'text-wrap: balance + 재분할');
    const txt = TXT(o), fam = FAM(o), wt = WGT(o), toks = words(txt);
    const bw = kf(t, [[0, 280], [1.7, 280], [2.3, 160], [4.2, 160], [4.5, 280], [4.8, 280]], E.inOut);
    let size = 34; let tw;
    const mw = () => { setFont(g, size, wt, fam); tw = toks.map(w => g.measureText(w).width); };
    const sp = s => /^\s+$/.test(s);
    const greedy = W => { const out = []; let cur = [], w = 0; toks.forEach((k, i) => { if (sp(k) && !cur.length) return; if (cur.length && !sp(k) && w + tw[i] > W) { while (cur.length && sp(toks[cur[cur.length - 1]])) cur.pop(); out.push(cur); cur = []; w = 0; } if (sp(k) && !cur.length) return; cur.push(i); w += tw[i]; }); while (cur.length && sp(toks[cur[cur.length - 1]])) cur.pop(); if (cur.length) out.push(cur); return out; };
    mw();
    for (let k = 0; k < 20 && (Math.max(...tw) > 136 || greedy(136).length > 3); k++) { size *= .9; mw(); }
    const balance = W => { const n = greedy(W).length; let lo = Math.max(...tw), hi = W; for (let k = 0; k < 14; k++) { const m = (lo + hi) / 2; if (greedy(m).length <= n) hi = m; else lo = m; } return greedy(hi); };
    const inner = bw - 24, lines = balance(inner).map(l => l.map(i => toks[i]).join(''));
    const lh = size * 1.18, H = lines.length * lh + 22, cy = 96;
    rr(g, 160 - bw / 2, cy - H / 2, bw, H, 8, K.card, K.grid, 1);
    // 상태: split → revert(리사이즈 중) → debounce → split
    const live = t >= 1.7 && t < 2.45, d = t < 2.45 ? .3 : 2.45, fade = 1 - seg(t, 4.2, 4.45, E.linear);
    lines.forEach((s, li) => {
      const y = cy + (li - (lines.length - 1) / 2) * lh;
      const Ly = layout(g, s, { o, size, maxW: 9999, maxLines: 1, minSize: size, y });
      if (live) { plain(g, Ly, K.mute); return; }
      const p = seg(t, d + li * .08, d + li * .08 + .6, E.outExpo);
      clip(g, 160 - bw / 2, y - lh / 2 - size * .1, bw, lh + size * .1, () => glyphs(g, Ly, () => ({ c: K.ink, dy: (1 - p) * lh, a: fade })));
      ln(g, 160 - Ly.width / 2, y + size * .5, 160 + Ly.width / 2, y + size * .5, K.grid, 1);
    });
    const st = live ? (t < 2.3 ? 'revert(리사이즈 중)' : 'debounce 150ms') : 'split → lines';
    t09Mono(g, st, 308, 14, live ? K.mute : K.red, 'right');
    const ws = lines.map(s => textW(g, s, size, wt, fam));
    t09Mono(g, `${lines.length}${L('행')} · ${L('차')} ${Math.round(Math.max(...ws) - Math.min(...ws))}px`, 160, 186, K.mute, 'center');
    const press = seg(t, 1.6, 1.7, E.linear) * (1 - seg(t, 2.3, 2.4, E.linear)) + seg(t, 4.1, 4.2, E.linear) * (1 - seg(t, 4.5, 4.6, E.linear));
    if (t > 1.3 && t < 2.7 || t > 3.9) cursor(g, 160 + bw / 2 - 2, cy + H / 2 - 12, press);
  },
  descEn: 'When the container width changes, the headline re-wraps into balanced lines of similar length, and the line-mask animation still plays correctly.',
  focus: '폭이 바뀌어도 행 길이는 고르게 유지된다(아래 수치가 행 길이의 차). 리사이즈 중에는 일단 분할을 되돌리고(회색), 멈춘 뒤 150ms 후 새 행으로 다시 분할해 마스크 움직임을 재생한다.',
  focusEn: 'Lines stay even at any width (the readout shows the length difference). While resizing, the split is reverted (grey); 150ms after it stops, the text is re-split into the new lines and the mask reveal replays.',
  caution: 'balance는 짧은 제목용(Chromium은 6행, Firefox는 10행까지). 행으로 분할한 애니메이션은 폭이 변하면 반드시 다시 분할한다(옛 행인 채로 두면 무너진다).',
  cautionEn: 'balance is for short headings (≤6 lines in Chromium, ≤10 in Firefox). Line-split animations must re-split on resize — stale lines break the layout.',
  values: ['text-wrap: balance', 'balance ≤ 6행', '리사이즈 debounce ≈ 150ms', 'SplitText autoSplit'],
  valuesEn: ['text-wrap: balance', 'balance ≤ 6 lines', 'resize debounce ≈ 150ms', 'SplitText autoSplit'],
  duration: 600, easing: 'easeOutExpo', feel: ['부드러움'], use: ['제목', 'UI'],
  recipes: {
    css: `h1 { text-wrap: balance; }\n/* 마스크 붙은 행은 JS로 분할(아래 GSAP) */\n@media (prefers-reduced-motion: reduce) { .line { transform: none !important; } }`,
    gsap: `// autoSplit: 폭이 변하면 자동으로 revert → 재분할하고 onSplit의 tween을 다시 만든다\nSplitText.create('h1', {\n  type: 'lines', mask: 'lines', autoSplit: true, aria: 'auto',\n  onSplit: self => gsap.from(self.lines, { yPercent: 100, duration: .6, ease: 'expo.out', stagger: .08 })\n});`,
    waapi: `// 자체 구현: ResizeObserver+debounce 150ms로 다시 분할\nlet id; new ResizeObserver(() => { clearTimeout(id); id = setTimeout(resplit, 150); }).observe(h1);\nfunction resplit() { h1.textContent = h1.dataset.text; splitLines(h1).forEach((l, i) =>\n  l.animate([{ transform: 'translateY(100%)' }, { transform: 'none' }], { duration: 600, delay: i * 80, easing: 'cubic-bezier(.16,1,.3,1)', fill: 'both' })); }`
  }
});

// 18. 행간 수렴
R({ id: 'line-spacing-collapse', dur: 3.8, ease: 'inOut', still: 2.4,
  f(g, t, o) {
    label(g, '행간: 크게 벌렸다가 → 좁히기');
    const txt = TXT(o), cjk = isCJK(txt), ws = t09Words(txt);
    let lines;
    if (ws.length >= 2) lines = t09Group(ws, Math.min(4, ws.length), cjk ? '' : ' ');
    else { const c = graphemes(txt); lines = c.length >= 4 && cjk ? t09Group(c, Math.min(3, Math.ceil(c.length / 3)), '') : [txt]; }
    const m = lines.length, fam = FAM(o), wt = WGT(o);
    const size = Math.min(m > 2 ? 30 : 36, ...lines.map(s => fitSize(g, s, 250, 36, wt, fam)));
    const lh = size * 1.12, E0 = m > 1 ? Math.min(56, (128 - (m - 1) * lh) / (m - 1)) : 0;
    const p = seg(t, .6, 1.6, E.inOut) * (1 - seg(t, 3.38, 3.75, E.inOut)), extra = E0 * (1 - p);
    const a = seg(t, .1, .45, E.linear) * (1 - seg(t, 3.0, 3.35, E.linear));
    const ys = lines.map((_, i) => 104 + (i - (m - 1) / 2) * (lh + extra));
    // 베이스라인의 가이드
    ys.forEach(y => ln(g, 30, y + size * .36, 290, y + size * .36, K.grid, 1));
    if (m > 1) alpha(g, a, () => { const y0 = ys[0] + size * .36, y1 = ys[m - 1] + size * .36; ln(g, 22, y0, 22, y1, K.red, 1.5); ln(g, 19, y0, 25, y0, K.red, 1.5); ln(g, 19, y1, 25, y1, K.red, 1.5); });
    lines.forEach((s, i) => { const Ly = layout(g, s, { o, size, maxW: 9999, maxLines: 1, minSize: size, y: ys[i] }); plain(g, Ly, i === m - 1 ? K.red : K.ink, a); });
    t09Mono(g, `${L('행간')} +${Math.round(extra / E0 * 120 || 0)}`, 308, 14, K.ink, 'right');
  },
  descEn: 'Lines that start far apart are drawn toward each other and settle into a tight paragraph.',
  focus: '글자 크기도 자간도 바뀌지 않고 행과 행의 거리만 줄어든다. 베이스라인(가는 선)과 왼쪽의 높이 눈금이 함께 좁아지며 흩어져 있던 행이 하나의 문단이 된다.',
  focusEn: 'Size and tracking never change — only the distance between lines shrinks. The baselines and the height bracket on the left close up together until the loose lines read as one paragraph.',
  caution: '펼쳐진 상태에서는 행의 연결이 읽히지 않으므로 수렴 후 확실히 멈춘다. 지나치게 좁혀 위아래 글자(특히 유럽문자의 g나 y)가 겹치지 않게 한다.',
  cautionEn: 'Spread-out lines don’t read as a sentence, so hold firmly once collapsed. Don’t over-tighten until descenders and ascenders collide.',
  values: ['행간 +120 → 0', '0.8–1.2초', 'ease-in-out', '기준: 행'],
  valuesEn: ['line spacing +120 → 0', '0.8–1.2 s', 'ease-in-out', 'based on lines'],
  duration: 1000, easing: 'easeInOut', feel: ['부드러움', '무거움'], use: ['제목', '영상'],
  recipes: {
    css: `/* 행별 span에 --i(중앙에서의 행 번호)를 넣는다 */\n.p .l { display: block; animation: close 1s cubic-bezier(.65,0,.35,1) .6s both; }\n@keyframes close { from { translate: 0 calc(var(--i) * 1.5em); } }\n@media (prefers-reduced-motion: reduce) { .p .l { animation: none; } }`,
    gsap: `const split = SplitText.create('.p', { type: 'lines', aria: 'auto' });\nconst mid = (split.lines.length - 1) / 2;\ngsap.from(split.lines, { y: i => (i - mid) * 56, duration: 1, ease: 'power2.inOut' });`,
    ae: '1. 텍스트 레이어 → 애니메이터: 행간(행송)\n2. 행간 (0, 120)\n3. 레인지 셀렉터 → 기준: 행\n4. 행간 값을 120 → 0으로 0.8–1.2초, 이지이즈',
    aeEn: '1. Text layer → Animate: Line Spacing\n2. Line Spacing (0, 120)\n3. Range Selector → Based On: Lines\n4. Animate 120 → 0 over 0.8–1.2 s with Easy Ease'
  }
});

// 19. 카메라 추종 키네틱
R({ id: 'kinetic-camera', dur: 6.0, bez: [.8, 0, .2, 1], still: 4.6,
  f(g, t, o) {
    label(g, '카메라: 팬·회전·줌');
    const txt = TXT(o), cjk = isCJK(txt), ph = t09Group(t09Words(txt), 4, cjk ? '' : ' '), n = ph.length;
    const fam = FAM(o), wt = WGT(o), SZ = [44, 30, 56, 36];
    const P = ph.map((s, i) => { const sz = SZ[i % 4], w = textW(g, s, sz, wt, fam), hh = sz * .82, rot = i % 2 ? Math.PI / 2 : 0; return { s, sz, w, hh, rot, bw: rot ? hh : w, bh: rot ? w : hh }; });
    P.forEach((p, i) => { if (!i) { p.l = 0; p.t = 0; return; } const q = P[i - 1];
      if (p.rot) { p.l = q.l + q.bw + 10; p.t = q.t; } else { p.t = q.t + q.bh + 10; p.l = q.l + q.bw - p.bw; } p.cx = 0; });
    P.forEach(p => { p.cx = p.l + p.bw / 2; p.cy = p.t + p.bh / 2; });
    const U = { l: Math.min(...P.map(p => p.l)), r: Math.max(...P.map(p => p.l + p.bw)), t: Math.min(...P.map(p => p.t)), b: Math.max(...P.map(p => p.t + p.bh)) };
    const view = p => ({ x: p.cx, y: p.cy, r: -p.rot, z: Math.min(220 / p.w, 70 / p.hh, 3) });
    const ov = { x: (U.l + U.r) / 2, y: (U.t + U.b) / 2, r: 0, z: Math.min(270 / (U.r - U.l), 140 / (U.b - U.t), 2) };
    const ez = bez(.8, 0, .2, 1), Pt = P.map((_, i) => .3 + i * .85), ovT = Pt[n - 1] + .7;
    const keys = [[0, view(P[0])]]; P.forEach((p, i) => { if (i) keys.push([Pt[i] - .4, view(P[i - 1])], [Pt[i], view(p)]); });
    keys.push([ovT, view(P[n - 1])], [ovT + .55, ov], [5.2, ov], [5.8, view(P[0])]);
    let cam = keys[keys.length - 1][1];
    for (let i = 1; i < keys.length; i++) if (t < keys[i][0]) { const [t0, A] = keys[i - 1], [t1, B] = keys[i], u = ez(clamp((t - t0) / (t1 - t0 || 1)));
      cam = { x: lerp(A.x, B.x, u), y: lerp(A.y, B.y, u), r: lerp(A.r, B.r, u), z: Math.exp(lerp(Math.log(A.z), Math.log(B.z), u)) }; break; }
    if (t < keys[0][0]) cam = keys[0][1];
    const fade = 1 - seg(t, 5.2, 5.6, E.linear);
    clip(g, 14, 24, 292, 152, () => {
      g.save(); g.translate(160, 100); g.scale(cam.z, cam.z); g.rotate(cam.r); g.translate(-cam.x, -cam.y);
      P.forEach((p, i) => {
        const dt = t - Pt[i], pop = dt < 0 ? 0 : kf(dt, [[0, .5], [.12, 1.08], [.24, 1]], E.outQuad), a = clamp(dt / .08) * fade;
        g.setLineDash([3 / cam.z, 3 / cam.z]); rr(g, p.l, p.t, p.bw, p.bh, 2 / cam.z, null, K.grid, 1 / cam.z); g.setLineDash([]);
        if (a <= 0) return;
        alpha(g, a, () => xf(g, p.cx, p.cy, pop, pop, p.rot, () => { setFont(g, p.sz, wt, fam); g.textAlign = 'center'; g.textBaseline = 'middle'; g.fillStyle = i === n - 1 ? K.red : K.ink; g.fillText(p.s, 0, 0); }));
      });
      g.restore();
    });
    // 파인더의 모서리
    [[18, 28, 1, 1], [302, 28, -1, 1], [18, 172, 1, -1], [302, 172, -1, -1]].forEach(([x, y, sx, sy]) => { ln(g, x, y, x + 10 * sx, y, K.mute, 1.2); ln(g, x, y, x, y + 10 * sy, K.mute, 1.2); });
    t09Mono(g, `rot ${Math.round(-cam.r * 180 / Math.PI)}°  ×${cam.z.toFixed(2)}`, 308, 14, K.ink, 'right');
    t09Mono(g, L('이동 0.4s·영향 80%'), 160, 188, K.mute, 'center');
  },
  descEn: 'Phrases of different sizes and orientations (rotated 90°) are laid out on a canvas, and a camera pans, rotates and zooms from one to the next.',
  focus: '글자는 움직이지 않고 카메라(화면 전체)가 단어에서 단어로 돌아간다. 90° 돌아간 단어에 도착하면 카메라도 90° 돌아서 어떤 단어도 정면으로 읽힌다. 마지막에 뒤로 빼면 전체 배치가 보인다.',
  focusEn: 'The words never move — the camera swings from one to the next. Arriving at a 90°-rotated phrase, the camera rotates 90° too, so every phrase reads level. Pulling back at the end reveals the whole arrangement.',
  caution: '회전과 줌을 동시에 빠르게 걸면 멀미하기 쉽다. 1회 이동은 8–12프레임이라도 도착 후 읽을 수 있는 만큼 멈춘다. 모션 감소 설정에서는 컷으로 이어붙인다.',
  cautionEn: 'Fast combined rotation and zoom can cause motion sickness. Moves can be 8–12 frames, but hold long enough to read after each arrival. With reduced motion, cut between phrases instead.',
  values: ['회전 90°	이동 8–12f', '이동 8–12f', '강한 이즈(영향 80%)', '단어별 팝인'],
  valuesEn: ['rotate 90°', '8–12 frame moves', 'strong ease (80% influence)', 'pop-in per phrase'],
  duration: 400, easing: 'cubic-bezier(.8,0,.2,1)', feel: ['경쾌함', '무거움'], use: ['영상', '광고'],
  recipes: {
    gsap: `// 내용을 움직이는 컨테이너 = 카메라. 각 프레이즈의 중심·각도·배율로 순서대로 옮겨간다\nconst tl = gsap.timeline({ defaults: { duration: .4, ease: 'expo.inOut' } });\nphrases.forEach(p => tl.to(stage, { x: -p.cx, y: -p.cy, rotation: -p.rot, scale: p.zoom, transformOrigin: '0 0' }).from(p.el, { scale: .5, autoAlpha: 0, duration: .24, ease: 'back.out(2)' }, '<.3').to({}, { duration: .45 }));`,
    remotion: `const cam = interpolate(frame, keyFrames, keyFrames.map((_, i) => i), { easing: Easing.bezier(.8, 0, .2, 1), extrapolateRight: 'clamp' });\nconst a = views[Math.floor(cam)], b = views[Math.ceil(cam)], u = cam % 1;\nreturn <AbsoluteFill style={{ transform: \`scale(\${lerp(a.z, b.z, u)}) rotate(\${lerp(a.r, b.r, u)}deg) translate(\${-lerp(a.x, b.x, u)}px, \${-lerp(a.y, b.y, u)}px)\` }}>{phrases}</AbsoluteFill>;`,
    ae: '1. 각 프레이즈를 별도 레이어로 배치(크기 다름, 일부는 90° 회전)\n2. 널을 만들고 전체 텍스트를 그 자식으로(널 = 카메라의 역)\n3. 널의 위치·회전·스케일을 단어마다 키, 8–12프레임\n4. 키프레임 속도: 영향 80%(강한 이즈), 단어는 오디오 마커로 팝인',
    aeEn: '1. Place each phrase on its own layer (varied sizes, some rotated 90°)\n2. Parent all text to a Null (the null is the inverse camera)\n3. Key the null’s Position / Rotation / Scale per phrase, 8–12 frames apart\n4. Keyframe Velocity: 80% influence (strong ease); pop words in on audio markers'
  }
});

// 20. 생략에서 전문 전개
R({ id: 'expand-truncated', dur: 4.8, ease: 'inOut', still: 2.4,
  samplesKo: ['이 문장은 첫 1행만 표시되고 나머지 부분은 생략되어 있습니다.', '더 읽기'],
  samplesEn: ['Only the first line of this text is shown; the rest of it is truncated.', 'Read more'],
  f(g, t, o) {
    label(g, 'line-clamp: 1 → 높이 auto');
    const P = TXTS(o), body = P[0], btn = (P[1] || '…').replace(/[…\.]+$/, '');
    const size = 14, cx0 = 46, cw = 228, tx0 = cx0 + 14, top = 30, tw = cw - 28;
    let Ly = layout(g, body, { o, size, maxW: tw, maxLines: 8, minSize: size, align: 'left', x: tx0, y: 0, weight: 600, lh: 1.5 });
    const nl = Ly.lines.length, lh = Ly.lineH, dy = top + 14 - Ly.top;
    const ex = seg(t, 1.1, 1.55, E.inOut) * (1 - seg(t, 3.6, 4.05, E.inOut));
    const h = lerp(lh, nl * lh, ex), ch = h + 28 + 22;
    rr(g, cx0, top, cw, ch, 8, K.card, K.grid, 1);
    // 글자(높이 h 창 안에서만. 하단은 마스크로 페이드)
    const reveal = top + 14 + h, ell = textW(g, '…', size, 600, Ly.family);
    const cut = tx0 + tw - ell - 2;
    clip(g, cx0, top + 10, cw, h + 6, () => glyphs(g, Ly, gl => {
      const gy = gl.y + dy, a = clamp((reveal - (gy - size * .9)) / (lh * .9));
      const trunc = nl > 1 && gl.li === 0 && gl.x + gl.w / 2 > cut ? ex : 1;
      return { c: K.ink, dy, a: Math.min(a, trunc) };
    }));
    if (nl > 1 && ex < 1) { const l0 = Ly.glyphs.filter(x => x.li === 0 && !x.space && x.x + x.w / 2 <= cut).pop(); if (l0) alpha(g, 1 - ex * 2, () => tx(g, '…', l0.x + l0.w / 2 + 1, Ly.lines[0].y + dy - size * .36 + 1, { a: 'left', size, w: 600, c: K.ink })); }
    // 버튼(내용 아래에 붙어 움직임)
    const by = top + 14 + h + 16;
    const lab = `${ex > .5 ? L('닫기') : btn} ${ex > .5 ? '▴' : '▾'}`;
    tx(g, lab, tx0, by, { a: 'left', size: 11, w: 700, c: K.red });
    // 아래 요소도 함께 밀려 내려감
    rr(g, cx0, top + ch + 8, cw, 14, 4, K.grid);
    t09Mono(g, `height ${Math.round(h)}px`, 308, 14, K.ink, 'right');
    t09Mono(g, '0.45s ease', 308, 188, K.mute, 'right');
    // 커서
    const tgt0 = [tx0 + 24, top + 14 + lh + 16 + 4], tgt1 = [tx0 + 24, top + 14 + nl * lh + 16 + 4];
    const cxk = kf(t, [[0, 262], [.5, 262], [.95, tgt0[0]], [1.25, tgt0[0]], [1.7, 292], [2.95, 292], [3.4, tgt1[0]], [4.1, tgt1[0]], [4.6, 262]], E.inOut);
    const cyk = kf(t, [[0, 186], [.5, 186], [.95, tgt0[1]], [1.25, tgt0[1]], [1.7, tgt1[1]], [2.95, tgt1[1]], [3.4, tgt1[1]], [4.1, tgt1[1]], [4.6, 186]], E.inOut);
    const press = seg(t, 1.0, 1.06, E.linear) * (1 - seg(t, 1.14, 1.2, E.linear)) + seg(t, 3.5, 3.56, E.linear) * (1 - seg(t, 3.64, 3.7, E.linear));
    cursor(g, cxk, cyk, press);
  },
  descEn: 'A sentence truncated to one line with “…” expands to the full text, the box growing in height to reveal the following lines.',
  focus: '상자 높이가 1행 분에서 전체 행 분으로 늘어나고, 추가된 줄은 아래쪽 마스크로 위에서부터 스며 나온다. 「...」는 사라지고 버튼과 아래 요소가 함께 밀려 내려간다.',
  focusEn: 'The box height grows from one line to the full text while the extra lines bleed in from the top under a moving mask. The “…” disappears and the button and the content below are pushed down together.',
  caution: '높이 애니메이션은 레이아웃 계산이 무거움(긴 문장이나 많은 카드에서 주의). 전개 후 포커스나 스크린리더 위치가 튀지 않도록 aria-expanded를 전환.',
  cautionEn: 'Animating height triggers layout on every frame — be careful with long text or many cards. Toggle aria-expanded so focus and screen-reader position stay put after expanding.',
  values: ['높이 1lh → auto	0.45s ease', '0.45s ease', 'interpolate-size: allow-keywords', '아래 요소는 FLIP'],
  valuesEn: ['height 1lh → auto', '0.45s ease', 'interpolate-size: allow-keywords', 'FLIP the content below'],
  duration: 450, easing: 'ease', feel: ['부드러움'], use: ['UI', '본문'],
  recipes: {
    css: `/* Chromium 129+: height:auto 보간 가능 */\n:root { interpolate-size: allow-keywords; }\n.more { height: 1lh; overflow: hidden; transition: height .45s ease;\n  mask-image: linear-gradient(#000 60%, transparent); }\n.more.open { height: auto; mask-image: none; }\n.more:not(.open) p { display: -webkit-box; -webkit-line-clamp: 1; -webkit-box-orient: vertical; }\n@media (prefers-reduced-motion: reduce) { .more { transition: none; } }`,
    waapi: `// 미대응 환경: scrollHeight를 재서 px로 보간 → 끝나면 auto로 되돌린다\nbtn.onclick = () => {\n  const from = box.offsetHeight; box.classList.add('open');\n  const to = box.scrollHeight;\n  box.animate([{ height: from + 'px' }, { height: to + 'px' }], { duration: 450, easing: 'ease' });\n  btn.setAttribute('aria-expanded', 'true');\n};`,
    motion: `<motion.div initial={false} animate={{ height: open ? 'auto' : '1.5em' }} transition={{ duration: .45, ease: 'easeInOut' }} style={{ overflow: 'hidden' }}>\n  <p style={open ? {} : { display: '-webkit-box', WebkitLineClamp: 1, WebkitBoxOrient: 'vertical' }}>{text}</p>\n</motion.div>\n<button aria-expanded={open} onClick={() => setOpen(!open)}>{open ? '닫기' : '더 읽기'}</button>`
  }
});

// ---- demos-t10.js ----
// ===== 텍스트 모션 레퍼런스 t10: 루프와 일본어 고유의 문자 연출 =====
// 작은 수치 읽기(mono)
function t10Read(g, s, x, y, c, a = 'center', size = 9) { tx(g, s, x, y, { a, size, f: 'm', w: 500, c: c || K.mute }); }
// 글자의 세로 중심(layout의 y는 베이스라인 쪽)
const t10Cy = (gl, L) => gl.y - L.size * .36;
// 문자열 전체의 외곽
function t10Box(L) { const ls = L.lines.length ? L.lines : [{ x: W / 2, w: 0 }]; const x0 = Math.min(...ls.map(l => l.x - l.w / 2)), x1 = Math.max(...ls.map(l => l.x + l.w / 2)); return { x0, x1, y0: L.top, y1: L.top + L.height, cx: (x0 + x1) / 2, cy: L.top + L.height / 2 }; }
// 글자 간격: 기본 each, 많을 때는 전체를 maxTotal 초로 조임
function t10Each(n, each, maxTotal) { return n > 1 ? Math.min(each, maxTotal / (n - 1)) : 0; }
// 색 토큰을 투명하게 만든 것(그라디언트용)
const t10Clear = c => c + '00';
// 한자(CJK 통합 한자·々)
const t10Han = c => /[㐀-鿿豈-﫿々]/.test(c);
// 히라가나 → 가타카나, 영숫자 → 전각
const t10Kata = s => s.replace(/[ぁ-ゖ]/g, c => String.fromCharCode(c.charCodeAt(0) + 0x60));
const t10Full = s => s.replace(/[!-~]/g, c => String.fromCharCode(c.charCodeAt(0) + 0xFEE0)).replace(/ /g, '　');
// 전각 1·반각 0.5로 셈(자막의 글자 수)
